            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) {
      console.error("Feedback Audio Error:", e);
    }
  };

  const handleOptionClick = (index: number) => {
    if (isAnswered) return;
    setSelectedOption(index);
    setIsAnswered(true);

    const isCorrect = index === questions[currentStep].correctIndex;
    if (isCorrect) {
      setScore(s => s + 1);
    }

    playFeedback(isCorrect);
  };

  const handleNext = () => {
    if (currentStep < questions.length - 1) {
      setCurrentStep(s => s + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowResult(true);
    }
  };

  const getStarRating = () => {
    if (score >= 9) return 3;
    if (score >= 7) return 2;
    if (score >= 5) return 1;
    return 0;
  };

  if (loading) {
    return (
      <div className="max-w-2xl mx-auto p-12 flex flex-col items-center justify-center space-y-6 fade-in min-h-screen">
        <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
        <div className="text-center space-y-2">
          <p className="text-xl font-bold text-emerald-800 animate-pulse">Menyusun soalan mengikut tahap...</p>
          <p className="text-sm text-gray-400 italic">Guru AI sedang menyiapkan kuiz {level.title} untuk anda.</p>
        </div>
        <Copyright />
      </div>
    );
  }

  if (showResult) {
    const stars = getStarRating();
    return (
      <div className="max-w-2xl mx-auto p-8 text-center space-y-8 animate-in fade-in duration-500 flex flex-col items-center min-h-screen">
        {/* Star Container */}
        <div className="flex justify-center space-x-2 mb-4">
          {[1, 2, 3].map((starIdx) => (
            <div 
              key={starIdx}
              className={`text-5xl transition-all duration-700 ${starIdx <= stars ? 'scale-110 drop-shadow-xl animate-bounce' : 'opacity-20 grayscale scale-90'}`}
              style={{ transitionDelay: `${starIdx * 150}ms` }}
            >
              ⭐
            </div>
          ))}
        </div>

        <div className="w-32 h-32 bg-emerald-100 rounded-full flex items-center justify-center mx-auto text-6xl shadow-inner relative">
          {stars === 3 ? '🏆' : (stars === 2 ? '🥇' : (stars === 1 ? '🎗️' : '💪'))}
          {stars === 3 && (
            <div className="absolute inset-0 bg-yellow-400/20 rounded-full animate-ping"></div>
          )}
        </div>

        <div className="space-y-2">
          <h2 className="text-4xl font-black text-gray-900 tracking-tight">
            {stars === 3 ? 'Mumtaz!' : (stars === 2 ? 'Jayyid Jiddan!' : (stars === 1 ? 'Jayyid!' : 'Teruskan Usaha!'))}
          </h2>
          <p className="text-xl text-gray-500 font-medium">Anda telah menyelesaikan kuiz {level.title}.</p>

          {onFinish && score >= 6 && (
            <div className="mt-4 animate-in fade-in duration-1000">
              <span className="px-6 py-2 bg-emerald-50 text-emerald-600 font-black rounded-full border border-emerald-100 text-sm uppercase tracking-widest shadow-sm">
                🎉 Tahap Seterusnya Telah Dibuka!
              </span>
            </div>
          )}
        </div>

        <div className="bg-white p-10 rounded-[3rem] shadow-2xl border-4 border-emerald-50 inline-block px-16 relative group">
          <div className="absolute -top-4 -left-4 w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shadow-lg transition-transform">🎯</div>
          <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.3em] mb-2">Markah Anda</p>
          <div className="flex items-baseline justify-center space-x-1">
            <span className="text-7xl font-black text-emerald-600">{score}</span>
            <span className="text-2xl font-bold text-gray-300">/ 10</span>
          </div>
        </div>

        <div className="pt-8 flex flex-col items-center space-y-4 flex-1 w-full">
          <button 
            onClick={onFinish || onBack}
            className="w-full max-w-sm px-16 py-6 bg-emerald-600 text-white rounded-[2rem] font-black shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all hover:scale-[1.02] active:scale-95 text-lg flex items-center justify-center space-x-3"
          >
            <span>Tutup & Simpan Progress</span>
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7"/></svg>
          </button>
          <button 
            onClick={() => window.location.reload()} 
            className="text-gray-400 font-bold hover:text-emerald-600 transition-colors flex items-center space-x-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
            <span>Ulang Kuiz Ini</span>
          </button>
        </div>
        <Copyright />
      </div>
    );
  }

  const currentQuestion = questions[currentStep];
  const difficultyLabel = currentStep < 3 ? 'Senang' : (currentStep < 7 ? 'Sederhana' : 'Sukar');
  const difficultyColor = currentStep < 3 ? 'emerald' : (currentStep < 7 ? 'blue' : 'rose');

  return (
    <div 
      className="max-w-2xl mx-auto p-4 md:p-8 animate-in fade-in duration-300 min-h-screen flex flex-col"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="flex items-center justify-between mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-colors flex items-center space-x-1 group">
          <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
          <span className="font-bold">Batal</span>
        </button>
        <div className="flex flex-col items-end">
          <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Kemajuan Kuiz</span>
          <div className="flex items-center space-x-3">
            <span className="text-xs font-bold text-gray-800">
              {currentStep + 1} <span className="text-gray-300">/ 10</span>
            </span>
            <div className="w-24 h-2 bg-gray-100 rounded-full overflow-hidden shadow-inner">
              <div 
                className="h-full bg-emerald-500 transition-all duration-700 ease-out" 
                style={{ width: `${((currentStep + 1) / 10) * 100}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-8 flex-1">
        <div className="bg-white p-8 sm:p-12 rounded-[2.5rem] shadow-xl border-2 border-emerald-50 relative overflow-hidden group animate-in fade-in duration-500">
          <div className={`absolute top-0 left-0 w-2 h-full bg-${difficultyColor}-500 transition-all duration-300`}></div>
          <div className="flex justify-center mb-6">
             <span className={`px-4 py-1.5 bg-${difficultyColor}-50 text-${difficultyColor}-600 text-[9px] font-black uppercase tracking-[0.2em] rounded-full border border-${difficultyColor}-100 shadow-sm`}>
               Tahap: {difficultyLabel}
             </span>
          </div>
          <h3 className="text-2xl sm:text-4xl font-black text-gray-900 text-center leading-relaxed arabic-text transition-transform duration-300">
            {currentQuestion?.question}
          </h3>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {currentQuestion?.options.map((option: string, index: number) => {
            let bgColor = "bg-white";
            let borderColor = "border-gray-100";
            let textColor = "text-gray-800";
            let animationClass = "";
            let icon = null;

            if (isAnswered) {
              if (index === currentQuestion.correctIndex) {
                bgColor = "bg-emerald-500";
                borderColor = "border-emerald-600 shadow-xl shadow-emerald-100";
                textColor = "text-white";
                animationClass = "animate-subtle-pulse scale-105";
                icon = (
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                  </svg>
                );
              } else if (selectedOption === index) {
                bgColor = "bg-rose-500";
                borderColor = "border-rose-600 shadow-xl shadow-rose-100";
                textColor = "text-white";
                animationClass = "animate-shake";
                icon = (
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                );
              } else {
                bgColor = "bg-gray-50";
                borderColor = "border-gray-100";
                textColor = "text-gray-300 opacity-50";
              }
            }

            return (
              <button
                key={index}
                onClick={() => handleOptionClick(index)}
                disabled={isAnswered}
                className={`relative p-8 rounded-[2rem] border-4 text-2xl font-bold transition-all duration-300 text-center flex flex-col items-center justify-center min-h-[160px] shadow-sm ${bgColor} ${borderColor} ${textColor} ${animationClass} ${!isAnswered ? 'hover:border-emerald-200 hover:shadow-2xl hover:scale-[1.02] active:scale-95' : ''}`}
              >
                <span className={`arabic-text text-5xl mb-2 transition-transform ${isAnswered && index === currentQuestion.correctIndex ? 'scale-110' : ''}`}>{option}</span>
                {icon && (
                  <div className="absolute top-4 right-4 animate-in zoom-in-0 duration-300">
                    {icon}
                  </div>
                )}
              </button>
            );
          })}
        </div>

        {isAnswered && (
          <div className="bg-emerald-50 p-8 rounded-[2.5rem] border-2 border-emerald-100 animate-in fade-in duration-300 shadow-xl shadow-emerald-100/30">
            <div className="flex items-start space-x-5">
              <div className={`mt-1 flex-shrink-0 w-12 h-12 rounded-2xl flex items-center justify-center text-2xl shadow-md ${selectedOption === currentQuestion.correctIndex ? 'bg-emerald-600 text-white' : 'bg-rose-500 text-white animate-shake'}`}>
                {selectedOption === currentQuestion.correctIndex ? '✨' : '💡'}
              </div>
              <div className="flex-1">
                <p className="font-black text-emerald-950 text-xl mb-1">
                  {selectedOption === currentQuestion.correctIndex ? 'Mumtaz!' : 'Oops, Sikit Lagi!'}
                </p>
                <p className="text-emerald-800 leading-relaxed font-medium text-sm">
                  {currentQuestion.explanation}
                </p>
              </div>
            </div>
            <div className="mt-8">
              <button
                onClick={handleNext}
                className="w-full py-5 bg-emerald-600 text-white rounded-3xl font-black text-lg hover:bg-emerald-700 transition-all shadow-xl hover:shadow-emerald-200 active:scale-95 flex items-center justify-center space-x-3 group"
              >
                <span>{currentStep === 9 ? 'Keputusan Akhir' : 'Soalan Seterusnya'}</span>
                <svg className="w-5 h-5 group-hover:translate-x-2 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 5l7 7-7 7" />
                </svg>
              </button>
            </div>
          </div>
        )}
      </div>
      <Copyright />
    </div>
  );
};

