      if (currentIndex === 13) return "Unit 3: Wajib Muttasil";
      if (currentIndex === 14) return "Unit 4: Jaiz Munfasil";
      if (currentIndex === 15) return "Unit 5: Arid Lissukun";
      if (currentIndex === 16) return "Unit 6: Mad Lazim";
      if (currentIndex >= 17 && currentIndex <= 21) return `Unit 7: Sederhana Gabungan (Halaman ${currentIndex - 16})`;
      if (currentIndex >= 22 && currentIndex <= 26) return `Unit 8: Sukar Gabungan (Halaman ${currentIndex - 21})`;
    }
    return level.title;
  }, [level.id, currentIndex]);

  if (isIqra8) {
    const currentWaqaf = (IQRA_8_DATA[currentIndex] as any);
    return (
      <div 
        className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh] bg-white"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <div className="w-full flex justify-between items-center mb-10">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-colors flex items-center space-x-2 group">
             <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-rose-50 transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
             </div>
             <span className="text-xs font-black uppercase tracking-widest">Batal</span>
          </button>
          <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
             <div className="h-full bg-rose-500 transition-all duration-700 shadow-sm" style={{ width: `${overallProgress}%` }}></div>
          </div>
          <div className="flex flex-col items-end">
            <span className="text-[9px] font-black text-rose-600 uppercase tracking-[0.3em]">Hukum Waqaf</span>
            <span className="text-sm font-bold text-gray-900">{currentStep} / {totalSteps}</span>
          </div>
        </div>

        <div className="w-full flex flex-col items-center space-y-12">
          {/* Rule Header */}
          <div className="w-full max-w-3xl bg-white p-10 rounded-[3rem] shadow-2xl shadow-rose-900/5 border border-rose-50 flex flex-col items-center text-center space-y-6">
            <div className="w-24 h-24 bg-rose-600 rounded-[2rem] flex items-center justify-center text-white text-5xl quranic-typography shadow-xl shadow-rose-200 rotate-3">
              {currentWaqaf.sign}
            </div>
            <div className="space-y-2">
              <h2 className="text-3xl font-black text-gray-900 tracking-tight">{currentWaqaf.name}</h2>
              <div className="px-6 py-2 bg-rose-50 text-rose-700 text-sm font-bold rounded-full border border-rose-100 italic">
                "{currentWaqaf.rule}"
              </div>
            </div>
          </div>

          {/* Clean Examples Area */}
          <div className="w-full space-y-12">
             <div className="flex items-center justify-center space-x-4 opacity-30">
                <div className="h-px w-12 bg-gray-300"></div>
                <span className="text-[10px] font-black uppercase tracking-[0.4em]">Latihan Bacaan</span>
                <div className="h-px w-12 bg-gray-300"></div>
             </div>

             <div className="w-full flex flex-col items-center space-y-16" dir="rtl">
               {currentWaqaf.examples.map((ex: string, idx: number) => (
                 <button 
                   key={idx}
                   onClick={() => handleBoxClick(ex, idx)}
                   disabled={isLoadingAudio}
                   className={`w-full max-w-4xl p-14 sm:p-20 bg-white rounded-[4rem] border-2 border-gray-50 shadow-sm hover:border-rose-300 hover:shadow-2xl transition-all duration-500 text-center relative group overflow-hidden ${isAnimating === idx ? 'scale-[0.98] border-rose-500 bg-rose-50/10' : ''}`}
                 >
                    <div className="absolute top-0 right-0 w-2 h-full bg-transparent group-hover:bg-rose-500/10 transition-all"></div>
                    <span className="quranic-typography text-4xl sm:text-5xl md:text-6xl text-gray-950 select-none block">
                      {ex}
                    </span>
                    {isLoadingAudio && isAnimating === idx && (
                      <div className="absolute top-10 left-10">
                        <div className="w-10 h-10 border-4 border-rose-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
                    )}
                 </button>
               ))}
             </div>
          </div>
        </div>

        <div className="w-full max-w-2xl grid grid-cols-2 gap-6 mt-16 pb-12">
          <button onClick={prevLetter} disabled={currentIndex === 0} className="py-6 bg-white border-2 border-gray-100 rounded-[2.5rem] font-black text-gray-400 hover:text-rose-600 hover:border-rose-100 disabled:opacity-20 transition-all uppercase tracking-widest text-[10px]">KEMBALI</button>
          <button onClick={nextLetter} className="py-6 bg-rose-600 rounded-[2.5rem] font-black text-white shadow-2xl shadow-rose-100 hover:bg-rose-700 hover:scale-[1.02] active:scale-95 transition-all uppercase tracking-widest text-[10px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
    );
  }

  const currentItem = data[currentIndex];
  const currentItems = Array.isArray(currentItem) ? currentItem : [currentItem];
  const isAdvancedLevel = level.id >= 6;

  return (
    <div 
      className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in duration-500 min-h-[70vh] bg-white"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-10">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-2 group`}>
           <div className={`w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-${colorTheme}-50 transition-all`}>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
           </div>
           <span className="text-xs font-black uppercase tracking-widest">Batal</span>
        </button>
        <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-700 shadow-sm`} style={{ width: `${overallProgress}%` }}></div>
        </div>
        <div className="flex flex-col items-end">
          <span className={`text-[9px] font-black text-${colorTheme}-600 uppercase tracking-[0.3em]`}>{mode === 'SEQUENTIAL' ? level.title : 'REVIEW'}</span>
          <span className="text-sm font-bold text-gray-900">{currentStep} / {totalSteps}</span>
        </div>
      </div>

      <div className="w-full flex flex-col items-center space-y-10">
        <div className="text-center space-y-4 max-w-2xl">
           <h2 className="text-4xl font-black text-gray-900 tracking-tight">{mode === 'SEQUENTIAL' ? pageTitle : 'Ulangkaji Huruf'}</h2>
           <p className="text-sm text-gray-400 font-medium uppercase tracking-widest">{level.subtitle}</p>
        </div>

        {mode === 'SEQUENTIAL' ? (
          <div className={`w-full grid gap-8 ${isIqra1 ? 'grid-cols-1 max-w-lg' : (isAdvancedLevel ? 'grid-cols-1 max-w-4xl' : 'grid-cols-2 sm:grid-cols-3 max-w-5xl')}`} dir="rtl">
            {currentItems.map((word, vIdx) => (
              <button 
                key={vIdx}
                onClick={() => handleBoxClick(word as string, vIdx)}
                disabled={isLoadingAudio}
                className={`w-full bg-white shadow-md border border-gray-100 text-gray-900 flex items-center justify-center transition-all duration-500 relative rounded-[3rem] sm:rounded-[4rem] px-8 py-16 sm:py-24 ${isAnimating === vIdx ? 'scale-95 border-emerald-400 ring-8 ring-emerald-50' : 'hover:scale-[1.02] hover:shadow-2xl hover:border-emerald-200'}`}
              >
                {isLoadingAudio && isAnimating === vIdx && (
                  <div className="absolute top-8 left-8"><div className={`w-8 h-8 border-4 border-${colorTheme}-500 border-t-transparent rounded-full animate-spin`}></div></div>
                )}
                <span className={`quranic-typography font-black text-center transition-transform duration-500 select-none antialiased ${isAnimating === vIdx ? 'scale-110' : ''} ${isIqra1 ? 'text-[15rem] sm:text-[20rem]' : (isAdvancedLevel ? 'text-4xl sm:text-6xl md:text-7xl' : 'text-3xl sm:text-4xl md:text-5xl')}`}>
