      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [showNotification, setShowNotification] = useState(true);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const touchStartX = useRef<number | null>(0);
  const touchEndX = useRef<number | null>(0);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    if (!hasReview) return [];
    const grids = [];

    let flatPool: string[] = [];
    if (level.id === 1) {
      flatPool = IQRA_1_LETTERS;
    } else if (level.id === 2) {
      flatPool = IQRA_2_DATA.flat();
    } else if (level.id === 3) {
      flatPool = IQRA_3_DATA.flat();
    } else if (level.id === 4) {
      const iqra4Pool = IQRA_4_DATA.flatMap(group => group.slice(3));
      const iqra3Pool = IQRA_3_DATA.flat();
      const iqra2Pool = IQRA_2_DATA.flat();
      flatPool = [...iqra4Pool, ...iqra3Pool, ...iqra2Pool];
    }

    for (let i = 0; i < 6; i++) {
      const shuffled = [...flatPool].sort(() => Math.random() - 0.5);
      grids.push(shuffled.slice(0, 16)); 
    }
    return grids;
  }, [level.id, hasReview]);

  useEffect(() => {
    setShowNotification(false);
    const timeout = setTimeout(() => setShowNotification(true), 10);
    return () => clearTimeout(timeout);
  }, [currentIndex, reviewPage, mode]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      if (hasReview) {
        setMode('REVIEW');
        setReviewPage(0);
      } else {
        onFinish();
      }
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < 5) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;

    const distance = touchStartX.current - touchEndX.current;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe) {
      if (mode === 'SEQUENTIAL') nextLetter();
      else nextReviewPage();
    } else if (isRightSwipe) {
      if (mode === 'SEQUENTIAL') prevLetter();
      else prevReviewPage();
    }
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = level.id >= 4 
        ? `Sebutkan ayat Al-Quran atau perkataan Arab ini dengan makhraj dan tajwid yang sempurna: ${letter}` 
        : `Sebutkan huruf hijaiyah ini dengan makhraj yang jelas: ${letter}`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 400);
  };

  const totalSteps = hasReview ? data.length + 6 : data.length;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  const pageTitle = useMemo(() => {
    if (level.id === 5) {
      if (currentIndex <= 8) return `Unit 1: Sukun (Halaman ${currentIndex + 1})`;
      if (currentIndex <= 12) return `Unit 2: Mad Asli (Halaman ${currentIndex - 8})`;
      if (currentIndex === 13) return "Unit 3: Wajib Muttasil";
      if (currentIndex === 14) return "Unit 4: Jaiz Munfasil";
      if (currentIndex === 15) return "Unit 5: Arid Lissukun";
      if (currentIndex === 16) return "Unit 6: Mad Lazim";
      if (currentIndex >= 17 && currentIndex <= 21) return `Unit 7: Sederhana Gabungan (Halaman ${currentIndex - 16})`;
      if (currentIndex >= 22 && currentIndex <= 26) return `Unit 8: Sukar Gabungan (Halaman ${currentIndex - 21})`;
    }
    return level.title;
  }, [level.id, currentIndex]);

  if (isIqra8) {
    const currentWaqaf = (IQRA_8_DATA[currentIndex] as any);
    return (
      <div 
        className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh] bg-white"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <div className="w-full flex justify-between items-center mb-10">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-colors flex items-center space-x-2 group">
             <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-rose-50 transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
             </div>
             <span className="text-xs font-black uppercase tracking-widest">Batal</span>
          </button>
          <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
             <div className="h-full bg-rose-500 transition-all duration-700 shadow-sm" style={{ width: `${overallProgress}%` }}></div>
          </div>
          <div className="flex flex-col items-end">
            <span className="text-[9px] font-black text-rose-600 uppercase tracking-[0.3em]">Hukum Waqaf</span>
            <span className="text-sm font-bold text-gray-900">{currentStep} / {totalSteps}</span>
          </div>
        </div>

        <div className="w-full flex flex-col items-center space-y-12">
          {/* Rule Header */}
          <div className="w-full max-w-3xl bg-white p-10 rounded-[3rem] shadow-2xl shadow-rose-900/5 border border-rose-50 flex flex-col items-center text-center space-y-6">
            <div className="w-24 h-24 bg-rose-600 rounded-[2rem] flex items-center justify-center text-white text-5xl quranic-typography shadow-xl shadow-rose-200 rotate-3">
              {currentWaqaf.sign}
            </div>
            <div className="space-y-2">
              <h2 className="text-3xl font-black text-gray-900 tracking-tight">{currentWaqaf.name}</h2>
              <div className="px-6 py-2 bg-rose-50 text-rose-700 text-sm font-bold rounded-full border border-rose-100 italic">
                "{currentWaqaf.rule}"
              </div>
            </div>
          </div>

          {/* Clean Examples Area */}
          <div className="w-full space-y-12">
             <div className="flex items-center justify-center space-x-4 opacity-30">
                <div className="h-px w-12 bg-gray-300"></div>
                <span className="text-[10px] font-black uppercase tracking-[0.4em]">Latihan Bacaan</span>
                <div className="h-px w-12 bg-gray-300"></div>
             </div>

             <div className="w-full flex flex-col items-center space-y-16" dir="rtl">
               {currentWaqaf.examples.map((ex: string, idx: number) => (
                 <button 
                   key={idx}
                   onClick={() => handleBoxClick(ex, idx)}
                   disabled={isLoadingAudio}
                   className={`w-full max-w-4xl p-14 sm:p-20 bg-white rounded-[4rem] border-2 border-gray-50 shadow-sm hover:border-rose-300 hover:shadow-2xl transition-all duration-500 text-center relative group overflow-hidden ${isAnimating === idx ? 'scale-[0.98] border-rose-500 bg-rose-50/10' : ''}`}
                 >
                    <div className="absolute top-0 right-0 w-2 h-full bg-transparent group-hover:bg-rose-500/10 transition-all"></div>
                    <span className="quranic-typography text-4xl sm:text-5xl md:text-6xl text-gray-950 select-none block">
                      {ex}
                    </span>
                    {isLoadingAudio && isAnimating === idx && (
                      <div className="absolute top-10 left-10">
                        <div className="w-10 h-10 border-4 border-rose-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
                    )}
                 </button>
               ))}
             </div>
          </div>
        </div>

        <div className="w-full max-w-2xl grid grid-cols-2 gap-6 mt-16 pb-12">
          <button onClick={prevLetter} disabled={currentIndex === 0} className="py-6 bg-white border-2 border-gray-100 rounded-[2.5rem] font-black text-gray-400 hover:text-rose-600 hover:border-rose-100 disabled:opacity-20 transition-all uppercase tracking-widest text-[10px]">KEMBALI</button>
          <button onClick={nextLetter} className="py-6 bg-rose-600 rounded-[2.5rem] font-black text-white shadow-2xl shadow-rose-100 hover:bg-rose-700 hover:scale-[1.02] active:scale-95 transition-all uppercase tracking-widest text-[10px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
    );
  }

  const currentItem = data[currentIndex];
  const currentItems = Array.isArray(currentItem) ? currentItem : [currentItem];
  const isAdvancedLevel = level.id >= 6;
  const typographyClass = level.id === 8 ? 'quranic-typography' : (isAdvancedLevel ? 'arabic-text text-4xl sm:text-6xl md:text-7xl leading-relaxed' : 'arabic-text text-3xl sm:text-4xl md:text-5xl');

  return (
    <div 
      className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in duration-500 min-h-[70vh] bg-white"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-10">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-2 group`}>
           <div className={`w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-${colorTheme}-50 transition-all`}>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
           </div>
           <span className="text-xs font-black uppercase tracking-widest">Batal</span>
        </button>
        <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-700 shadow-sm`} style={{ width: `${overallProgress}%` }}></div>
        </div>
        <div className="flex flex-col items-end">
          <span className={`text-[9px] font-black text-${colorTheme}-600 uppercase tracking-[0.3em]`}>{mode === 'SEQUENTIAL' ? level.title : 'REVIEW'}</span>
          <span className="text-sm font-bold text-gray-900">{currentStep} / {totalSteps}</span>
        </div>
      </div>

      <div className="w-full flex flex-col items-center space-y-10">
        <div className="text-center space-y-4 max-w-2xl">
           <h2 className="text-4xl font-black text-gray-900 tracking-tight">{mode === 'SEQUENTIAL' ? pageTitle : 'Ulangkaji Huruf'}</h2>
           <p className="text-sm text-gray-400 font-medium uppercase tracking-widest">{level.subtitle}</p>
        </div>

        {mode === 'SEQUENTIAL' ? (
          <div className={`w-full grid gap-8 ${isIqra1 ? 'grid-cols-1 max-w-lg' : (isAdvancedLevel ? 'grid-cols-1 max-w-4xl' : 'grid-cols-2 sm:grid-cols-3 max-w-5xl')}`} dir="rtl">
            {currentItems.map((word, vIdx) => (
              <button 
                key={vIdx}
                onClick={() => handleBoxClick(word as string, vIdx)}
                disabled={isLoadingAudio}
                className={`w-full bg-white shadow-md border border-gray-100 text-gray-900 flex items-center justify-center transition-all duration-500 relative rounded-[3rem] sm:rounded-[4rem] px-8 py-16 sm:py-24 ${isAnimating === vIdx ? 'scale-95 border-emerald-400 ring-8 ring-emerald-50' : 'hover:scale-[1.02] hover:shadow-2xl hover:border-emerald-200'}`}
              >
                {isLoadingAudio && isAnimating === vIdx && (
                  <div className="absolute top-8 left-8"><div className={`w-8 h-8 border-4 border-${colorTheme}-500 border-t-transparent rounded-full animate-spin`}></div></div>
                )}
                <span className={`${typographyClass} font-black text-center transition-transform duration-500 select-none antialiased ${isAnimating === vIdx ? 'scale-110' : ''} ${isIqra1 ? 'text-[15rem] sm:text-[20rem]' : ''}`}>
                  {word as string}
                </span>
              </button>
            ))}
          </div>
        ) : (
          <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-6 w-full max-w-3xl bg-emerald-50/30 p-10 rounded-[4rem] border border-emerald-100/50 shadow-inner" dir="rtl">
              {reviewGrids[reviewPage]?.map((letter: string, idx: number) => (
                <button
                  key={`${reviewPage}-${idx}`}
                  onClick={() => handleBoxClick(letter, idx)}
                  disabled={isLoadingAudio}
                  className={`aspect-square bg-white rounded-[2rem] shadow-sm flex items-center justify-center transition-all duration-500 border border-transparent hover:border-emerald-300 relative ${isAnimating === idx ? 'scale-90 border-emerald-500 shadow-xl' : 'hover:scale-105 active:scale-95 hover:shadow-lg'}`}
                >
                   {isLoadingAudio && isAnimating === idx && (
                    <div className="absolute top-2 left-2"><div className="w-3 h-3 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div></div>
                  )}
                  <span className={`${typographyClass} font-black text-4xl leading-none text-emerald-950 transition-transform duration-500 select-none ${isAnimating === idx ? 'scale-125' : ''}`}>
                    {letter}
                  </span>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-6 mt-16 pb-12">
        <button onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage} disabled={mode === 'SEQUENTIAL' && currentIndex === 0} className="py-6 bg-white border-2 border-gray-100 rounded-[2.5rem] font-black text-gray-400 hover:text-emerald-600 hover:border-emerald-100 disabled:opacity-20 transition-all uppercase tracking-widest text-[10px]">KEMBALI</button>
        <button onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage} className={`py-6 bg-${colorTheme}-600 rounded-[2.5rem] font-black text-white shadow-2xl shadow-${colorTheme}-100 hover:brightness-110 hover:scale-[1.02] active:scale-95 transition-all uppercase tracking-widest text-[10px]`}>
          {mode === 'SEQUENTIAL' ? (currentIndex === data.length - 1 ? (hasReview ? 'Mula Review' : 'Selesai') : 'SETERUSNYA') : (reviewPage === 5 ? 'SELESAI' : 'SETERUSNYA')}
        </button>
      </div>
      <Copyright />
    </div>
  );
};

export default PracticeSession;

import React, { useState, useEffect, useRef } from 'react';
import { IqraLevel } from '../types';
import { getQuizQuestions } from '../services/geminiService';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface QuizProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish?: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const Quiz: React.FC<QuizProps> = ({ level, onBack, onFinish }) => {
  const [questions, setQuestions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentStep, setCurrentStep] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [showResult, setShowResult] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const typographyClass = level.id === 8 ? 'quranic-typography' : 'arabic-text';

  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  useEffect(() => {
    async function loadQuiz() {
      setLoading(true);
      const data = await getQuizQuestions(level.id, level.title, level.subtitle, 10);
      if (data && data.questions) {
        setQuestions(data.questions);
      }
      setLoading(false);
    }
    loadQuiz();
  }, [level]);

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current || !isAnswered) return;

    const distance = touchStartX.current - touchEndX.current;
    if (distance < -minSwipeDistance) {
      handleNext();
    }
  };

  const playFeedback = async (isCorrect: boolean) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const text = isCorrect ? "Alhamdulillah, Bagus! Jawapan anda tepat." : "Cuba lagi ya, anda pasti boleh!";

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) {
      console.error("Feedback Audio Error:", e);
    }
  };

  const handleOptionClick = (index: number) => {
    if (isAnswered) return;
    setSelectedOption(index);
    setIsAnswered(true);

    const isCorrect = index === questions[currentStep].correctIndex;
    if (isCorrect) {
      setScore(s => s + 1);
    }

    playFeedback(isCorrect);
  };

  const handleNext = () => {
    if (currentStep < questions.length - 1) {
      setCurrentStep(s => s + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowResult(true);
    }
  };

  if (loading) {
    return (
      <div className="max-w-2xl mx-auto p-12 flex flex-col items-center justify-center space-y-6 fade-in min-h-screen">
        <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
        <div className="text-center space-y-2">
          <p className="text-xl font-bold text-emerald-800 animate-pulse">Menyusun soalan mengikut tahap...</p>
          <p className="text-sm text-gray-400 italic">Menganalisis silibus {level.title} untuk anda.</p>
        </div>
        <Copyright />
      </div>
    );
  }

  if (showResult) {
    return (
      <div className="max-w-2xl mx-auto p-8 text-center space-y-8 animate-in zoom-in-95 duration-500 flex flex-col items-center min-h-screen">
        <div className="w-32 h-32 bg-emerald-100 rounded-full flex items-center justify-center mx-auto text-6xl shadow-inner animate-bounce">
          {score >= questions.length * 0.8 ? '🏆' : (score >= questions.length * 0.5 ? '⭐' : '💪')}
        </div>
        <div className="space-y-2">
          <h2 className="text-4xl font-black text-gray-900">
            {score === questions.length ? 'Mumtaz!' : (score >= questions.length * 0.7 ? 'Jayyid Jiddan!' : 'Teruskan Usaha!')}
          </h2>
          <p className="text-xl text-gray-500">Anda telah menyelesaikan kuiz {level.title}.</p>
          {onFinish && score >= questions.length * 0.6 && (
            <p className="text-emerald-600 font-bold bg-emerald-50 py-3 px-6 rounded-2xl mt-4 border border-emerald-100 inline-block animate-pulse">
              🎉 Tahap Seterusnya Telah Dibuka!
            </p>
          )}
        </div>
        <div className="bg-white p-10 rounded-[3rem] shadow-2xl border-4 border-emerald-50 inline-block px-20 relative">
          <div className="absolute -top-4 -left-4 w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shadow-lg animate-float">🎯</div>
          <p className="text-sm text-gray-400 font-black uppercase tracking-[0.2em] mb-2">Skor Akhir</p>
          <p className="text-7xl font-black text-emerald-600">{score} / {questions.length}</p>
        </div>
        <div className="pt-8 flex flex-col items-center space-y-4 flex-1">
          <button 
            onClick={onFinish || onBack}
            className="px-16 py-5 bg-emerald-600 text-white rounded-3xl font-bold shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all hover:scale-105 active:scale-95 text-lg"
          >
            Selesai & Kembali
          </button>
          <button onClick={onBack} className="text-gray-400 font-bold hover:text-rose-500 transition-colors">Tutup Kuiz</button>
        </div>
        <Copyright />
      </div>
    );
  }

  const currentQuestion = questions[currentStep];

  return (
    <div 
      className="max-w-2xl mx-auto p-4 md:p-8 animate-in fade-in slide-in-from-bottom-4 min-h-screen flex flex-col"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="flex items-center justify-between mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors flex items-center space-x-1 group">
          <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
          <span className="font-bold">Batal</span>
        </button>
        <div className="flex flex-col items-end">
          <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Progress Kuiz</span>
          <div className="flex items-center space-x-2">
            <span className="text-xs font-bold text-gray-400">
              {currentStep + 1} / {questions.length}
            </span>
            <div className="w-24 h-2 bg-gray-100 rounded-full overflow-hidden shadow-inner">
              <div 
                className="h-full bg-emerald-500 transition-all duration-700 ease-out" 
                style={{ width: `${((currentStep + 1) / questions.length) * 100}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-8 flex-1">
        <div className="bg-white p-8 sm:p-12 rounded-[2.5rem] shadow-xl border-2 border-emerald-50 relative overflow-hidden group hover:shadow-2xl transition-all duration-500">
          <div className="absolute top-0 left-0 w-3 h-full bg-emerald-500 group-hover:w-4 transition-all duration-300"></div>
          <div className="flex justify-center mb-4">
             <span className="px-4 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase tracking-widest rounded-full border border-emerald-100 shadow-sm">
               {currentStep < 3 ? 'TAHAP: SENANG' : (currentStep < 7 ? 'TAHAP: SEDERHANA' : 'TAHAP: SUKAR')}
             </span>
          </div>
          <h3 className={`${typographyClass} text-2xl sm:text-3xl font-black text-gray-900 text-center leading-relaxed transition-transform duration-300 group-hover:scale-[1.02]`}>
            {currentQuestion?.question}
          </h3>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {currentQuestion?.options.map((option: string, index: number) => {
            let bgColor = "bg-white";
            let borderColor = "border-gray-100";
            let textColor = "text-gray-700";
            let animationClass = "";
            let icon = null;

            if (isAnswered) {
              if (index === currentQuestion.correctIndex) {
                bgColor = "bg-emerald-500";
                borderColor = "border-emerald-600 shadow-xl shadow-emerald-100";
                textColor = "text-white";
                animationClass = "animate-subtle-pulse";
                icon = (
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                  </svg>
                );
              } else if (selectedOption === index) {
                bgColor = "bg-rose-500";
                borderColor = "border-rose-600 shadow-xl shadow-rose-100";
                textColor = "text-white";
                animationClass = "animate-shake";
                icon = (
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                );
              } else {
                bgColor = "bg-gray-50";
                borderColor = "border-gray-100";
                textColor = "text-gray-300 opacity-50";
              }
            }

            return (
              <button
                key={index}
                onClick={() => handleOptionClick(index)}
                disabled={isAnswered}
                className={`relative p-6 rounded-3xl border-4 text-xl font-bold transition-all duration-300 text-center flex flex-col items-center justify-center min-h-[140px] shadow-sm ${bgColor} ${borderColor} ${textColor} ${animationClass} ${!isAnswered ? 'hover:border-emerald-300 hover:shadow-2xl hover:-translate-y-2 active:scale-95' : ''}`}
              >
                <span className={`${typographyClass} text-4xl mb-1 transition-transform duration-300 ${isAnswered && index === currentQuestion.correctIndex ? 'scale-110' : ''}`}>{option}</span>
                {isAnswered && index === currentQuestion.correctIndex && (
                  <span className="text-[10px] font-black uppercase tracking-widest opacity-80">Jawapan Betul</span>
                )}
                {icon && (
                  <div className="absolute top-3 right-3 animate-in zoom-in-0 duration-300">
                    {icon}
                  </div>
                )}
              </button>
            );
          })}
        </div>

        {isAnswered && (
          <div className="bg-emerald-50 p-8 rounded-[2rem] border-2 border-emerald-100 animate-in slide-in-from-top-4 shadow-xl shadow-emerald-100/50">
            <div className="flex items-start space-x-4">
              <div className={`mt-1 flex-shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center text-xl shadow-md transition-transform duration-500 animate-bounce ${selectedOption === currentQuestion.correctIndex ? 'bg-emerald-600 text-white' : 'bg-rose-500 text-white'}`}>
                {selectedOption === currentQuestion.correctIndex ? '✅' : '💡'}
              </div>
              <div className="flex-1">
                <p className="font-black text-emerald-900 text-xl mb-1">
                  {selectedOption === currentQuestion.correctIndex ? 'Mumtaz! (Hebat)' : 'Belajar Sesuatu!'}
                </p>
                <p className="text-emerald-800 leading-relaxed font-medium">
                  {currentQuestion.explanation}
                </p>
              </div>
            </div>
            <div className="mt-8 space-y-3">
              <button
                onClick={handleNext}
                className="w-full py-5 bg-emerald-600 text-white rounded-2xl font-black text-lg hover:bg-emerald-700 transition-all shadow-lg hover:shadow-emerald-200 active:scale-[0.98] flex items-center justify-center space-x-2 group"
              >
                <span>{currentStep === questions.length - 1 ? 'Lihat Keputusan Akhir' : 'Soalan Seterusnya'}</span>
                <svg className="w-5 h-5 group-hover:translate-x-2 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 5l7 7-7 7" />
                </svg>
              </button>
              <p className="text-center text-emerald-400 text-[10px] font-bold uppercase tracking-widest">
                Tips: Swipe <b>Kanan</b> untuk Seterusnya
              </p>
            </div>
          </div>
        )}
      </div>
      <Copyright />
    </div>
  );
};

export default Quiz;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const hasReview = level.id >= 1 && level.id <= 4; 
  const isIqra8 = level.id === 8;
  const isIqra7 = level.id === 7;
  const isIqra6 = level.id === 6;
  const isIqra1 = level.id === 1;

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [showNotification, setShowNotification] = useState(true);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const touchStartX = useRef<number | null>(0);
  const touchEndX = useRef<number | null>(0);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    if (!hasReview) return [];
    const grids = [];

    let flatPool: string[] = [];
    if (level.id === 1) {
      flatPool = IQRA_1_LETTERS;
    } else if (level.id === 2) {
      flatPool = IQRA_2_DATA.flat();
    } else if (level.id === 3) {
      flatPool = IQRA_3_DATA.flat();
    } else if (level.id === 4) {
      const iqra4Pool = IQRA_4_DATA.flatMap(group => group.slice(3));
      const iqra3Pool = IQRA_3_DATA.flat();
      const iqra2Pool = IQRA_2_DATA.flat();
      flatPool = [...iqra4Pool, ...iqra3Pool, ...iqra2Pool];
    }

    for (let i = 0; i < 6; i++) {
      const shuffled = [...flatPool].sort(() => Math.random() - 0.5);
      grids.push(shuffled.slice(0, 16)); 
    }
    return grids;
  }, [level.id, hasReview]);

  useEffect(() => {
    setShowNotification(false);
    const timeout = setTimeout(() => setShowNotification(true), 10);
    return () => clearTimeout(timeout);
  }, [currentIndex, reviewPage, mode]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      if (hasReview) {
        setMode('REVIEW');
        setReviewPage(0);
      } else {
        onFinish();
      }
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < 5) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;

    const distance = touchStartX.current - touchEndX.current;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe) {
      if (mode === 'SEQUENTIAL') nextLetter();
      else nextReviewPage();
    } else if (isRightSwipe) {
      if (mode === 'SEQUENTIAL') prevLetter();
      else prevReviewPage();
    }
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = level.id >= 4 
        ? `Sebutkan ayat Al-Quran atau perkataan Arab ini dengan makhraj dan tajwid yang sempurna: ${letter}` 
        : `Sebutkan huruf hijaiyah ini dengan makhraj yang jelas: ${letter}`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 400);
  };

  const totalSteps = hasReview ? data.length + 6 : data.length;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  const pageTitle = useMemo(() => {
    if (level.id === 5) {
      if (currentIndex <= 8) return `Unit 1: Sukun (Halaman ${currentIndex + 1})`;
      if (currentIndex <= 12) return `Unit 2: Mad Asli (Halaman ${currentIndex - 8})`;
      if (currentIndex === 13) return "Unit 3: Wajib Muttasil";
      if (currentIndex === 14) return "Unit 4: Jaiz Munfasil";
      if (currentIndex === 15) return "Unit 5: Arid Lissukun";
      if (currentIndex === 16) return "Unit 6: Mad Lazim";
      if (currentIndex >= 17 && currentIndex <= 21) return `Unit 7: Sederhana Gabungan (Halaman ${currentIndex - 16})`;
      if (currentIndex >= 22 && currentIndex <= 26) return `Unit 8: Sukar Gabungan (Halaman ${currentIndex - 21})`;
    }
    return level.title;
  }, [level.id, currentIndex]);

  if (isIqra8) {
    const currentWaqaf = (IQRA_8_DATA[currentIndex] as any);
    return (
      <div 
        className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh] bg-white"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <div className="w-full flex justify-between items-center mb-10">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-colors flex items-center space-x-2 group">
             <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-rose-50 transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
             </div>
             <span className="text-xs font-black uppercase tracking-widest">Batal</span>
          </button>
          <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
             <div className="h-full bg-rose-500 transition-all duration-700 shadow-sm" style={{ width: `${overallProgress}%` }}></div>
          </div>
          <div className="flex flex-col items-end">
            <span className="text-[9px] font-black text-rose-600 uppercase tracking-[0.3em]">Hukum Waqaf</span>
            <span className="text-sm font-bold text-gray-900">{currentStep} / {totalSteps}</span>
          </div>
        </div>

        <div className="w-full flex flex-col items-center space-y-12">
          {/* Rule Header */}
          <div className="w-full max-w-3xl bg-white p-10 rounded-[3rem] shadow-2xl shadow-rose-900/5 border border-rose-50 flex flex-col items-center text-center space-y-6">
            <div className="w-24 h-24 bg-rose-600 rounded-[2rem] flex items-center justify-center text-white text-5xl quranic-typography shadow-xl shadow-rose-200 rotate-3">
              {currentWaqaf.sign}
            </div>
            <div className="space-y-2">
              <h2 className="text-3xl font-black text-gray-900 tracking-tight">{currentWaqaf.name}</h2>
              <div className="px-6 py-2 bg-rose-50 text-rose-700 text-sm font-bold rounded-full border border-rose-100 italic">
                "{currentWaqaf.rule}"
              </div>
            </div>
          </div>

          {/* Clean Examples Area */}
          <div className="w-full space-y-12">
             <div className="flex items-center justify-center space-x-4 opacity-30">
                <div className="h-px w-12 bg-gray-300"></div>
                <span className="text-[10px] font-black uppercase tracking-[0.4em]">Latihan Bacaan</span>
                <div className="h-px w-12 bg-gray-300"></div>
             </div>

             <div className="w-full flex flex-col items-center space-y-16" dir="rtl">
               {currentWaqaf.examples.map((ex: string, idx: number) => (
                 <button 
                   key={idx}
                   onClick={() => handleBoxClick(ex, idx)}
                   disabled={isLoadingAudio}
                   className={`w-full max-w-4xl p-20 sm:p-24 bg-white rounded-[5rem] border-2 border-gray-50 shadow-sm hover:border-rose-300 hover:shadow-2xl transition-all duration-500 text-center relative group overflow-hidden ${isAnimating === idx ? 'scale-[0.98] border-rose-500 bg-rose-50/10' : ''}`}
                 >
                    <div className="absolute top-0 right-0 w-2 h-full bg-transparent group-hover:bg-rose-500/10 transition-all"></div>
                    <span className="quranic-typography text-5xl sm:text-6xl md:text-8xl text-gray-950 select-none block">
                      {ex}
                    </span>
                    {isLoadingAudio && isAnimating === idx && (
                      <div className="absolute top-10 left-10">
                        <div className="w-12 h-12 border-4 border-rose-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
                    )}
                 </button>
               ))}
             </div>
          </div>
        </div>

        <div className="w-full max-w-2xl grid grid-cols-2 gap-6 mt-16 pb-12">
          <button onClick={prevLetter} disabled={currentIndex === 0} className="py-6 bg-white border-2 border-gray-100 rounded-[2.5rem] font-black text-gray-400 hover:text-rose-600 hover:border-rose-100 disabled:opacity-20 transition-all uppercase tracking-widest text-[10px]">KEMBALI</button>
          <button onClick={nextLetter} className="py-6 bg-rose-600 rounded-[2.5rem] font-black text-white shadow-2xl shadow-rose-100 hover:bg-rose-700 hover:scale-[1.02] active:scale-95 transition-all uppercase tracking-widest text-[10px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
    );
  }

  const currentItem = data[currentIndex];
  const currentItems = Array.isArray(currentItem) ? currentItem : [currentItem];
  const isAdvancedLevel = level.id >= 6;
  const typographyClass = level.id === 8 ? 'quranic-typography' : (isAdvancedLevel ? 'arabic-text text-4xl sm:text-6xl md:text-7xl leading-relaxed' : 'arabic-text text-3xl sm:text-4xl md:text-5xl');

  return (
    <div 
      className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in duration-500 min-h-[70vh] bg-white"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-10">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-2 group`}>
           <div className={`w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-${colorTheme}-50 transition-all`}>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
           </div>
           <span className="text-xs font-black uppercase tracking-widest">Batal</span>
        </button>
        <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-700 shadow-sm`} style={{ width: `${overallProgress}%` }}></div>
        </div>
        <div className="flex flex-col items-end">
          <span className={`text-[9px] font-black text-${colorTheme}-600 uppercase tracking-[0.3em]`}>{mode === 'SEQUENTIAL' ? level.title : 'REVIEW'}</span>
          <span className="text-sm font-bold text-gray-900">{currentStep} / {totalSteps}</span>
        </div>
      </div>

      <div className="w-full flex flex-col items-center space-y-10">
        <div className="text-center space-y-4 max-w-2xl">
           <h2 className="text-4xl font-black text-gray-900 tracking-tight">{mode === 'SEQUENTIAL' ? pageTitle : 'Ulangkaji Huruf'}</h2>
           <p className="text-sm text-gray-400 font-medium uppercase tracking-widest">{level.subtitle}</p>
        </div>

        {mode === 'SEQUENTIAL' ? (
          <div className={`w-full grid gap-8 ${isIqra1 ? 'grid-cols-1 max-w-lg' : (isAdvancedLevel ? 'grid-cols-1 max-w-4xl' : 'grid-cols-2 sm:grid-cols-3 max-w-5xl')}`} dir="rtl">
            {currentItems.map((word, vIdx) => (
              <button 
                key={vIdx}
                onClick={() => handleBoxClick(word as string, vIdx)}
                disabled={isLoadingAudio}
                className={`w-full bg-white shadow-md border border-gray-100 text-gray-900 flex items-center justify-center transition-all duration-500 relative rounded-[3rem] sm:rounded-[4rem] px-8 py-16 sm:py-24 ${isAnimating === vIdx ? 'scale-95 border-emerald-400 ring-8 ring-emerald-50' : 'hover:scale-[1.02] hover:shadow-2xl hover:border-emerald-200'}`}
              >
                {isLoadingAudio && isAnimating === vIdx && (
                  <div className="absolute top-8 left-8"><div className={`w-8 h-8 border-4 border-${colorTheme}-500 border-t-transparent rounded-full animate-spin`}></div></div>
                )}
                <span className={`${typographyClass} font-black text-center transition-transform duration-500 select-none antialiased ${isAnimating === vIdx ? 'scale-110' : ''} ${isIqra1 ? 'text-[15rem] sm:text-[20rem]' : ''}`}>
                  {word as string}
                </span>
              </button>
            ))}
          </div>
        ) : (
          <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-6 w-full max-w-3xl bg-emerald-50/30 p-10 rounded-[4rem] border border-emerald-100/50 shadow-inner" dir="rtl">
              {reviewGrids[reviewPage]?.map((letter: string, idx: number) => (
                <button
                  key={`${reviewPage}-${idx}`}
                  onClick={() => handleBoxClick(letter, idx)}
                  disabled={isLoadingAudio}
                  className={`aspect-square bg-white rounded-[2rem] shadow-sm flex items-center justify-center transition-all duration-500 border border-transparent hover:border-emerald-300 relative ${isAnimating === idx ? 'scale-90 border-emerald-500 shadow-xl' : 'hover:scale-105 active:scale-95 hover:shadow-lg'}`}
                >
                   {isLoadingAudio && isAnimating === idx && (
                    <div className="absolute top-2 left-2"><div className="w-3 h-3 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div></div>
                  )}
