              <h2 className="text-2xl font-black text-gray-900 tracking-tight">{currentWaqaf.name}</h2>
              <div className="px-5 py-1.5 bg-rose-50 text-rose-700 text-xs font-bold rounded-full border border-rose-100 italic">
                "{currentWaqaf.rule}"
              </div>
            </div>
          </div>

