                <span className="text-[9px] font-black uppercase tracking-[0.4em]">Latihan Bacaan</span>
                <div className="h-px w-10 bg-gray-300"></div>
             </div>

             <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6" dir="rtl">
               {currentWaqaf.examples.map((ex: string, idx: number) => (
                 <button 
                   key={idx}
                   onClick={() => handleBoxClick(ex, idx)}
                   disabled={isLoadingAudio}
                   className={`bg-white rounded-[2.5rem] border-2 border-gray-50 shadow-sm p-8 flex items-center justify-center text-center relative group overflow-hidden transition-all duration-500 ${isAnimating === idx ? 'scale-95 border-rose-500 bg-rose-50/20' : 'hover:border-rose-200 hover:shadow-xl hover:-translate-y-1'}`}
                 >
                    <div className="absolute top-0 right-0 w-1 h-full bg-transparent group-hover:bg-rose-500/10 transition-all"></div>
                    <span className="quranic-typography text-xl sm:text-2xl text-gray-950 select-none block leading-[2.2]">
                      {ex}
                    </span>
                    {isLoadingAudio && isAnimating === idx && (
                      <div className="absolute top-4 left-4">
                        <div className="w-6 h-6 border-3 border-rose-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
                    )}
                 </button>
               ))}
             </div>
          </div>
        </div>

        <div className="w-full max-w-xl grid grid-cols-2 gap-4 mt-16 pb-12">
          <button onClick={prevLetter} disabled={currentIndex === 0} className="py-5 bg-white border-2 border-gray-100 rounded-[2rem] font-black text-gray-400 hover:text-rose-600 hover:border-rose-100 disabled:opacity-20 transition-all uppercase tracking-widest text-[9px]">KEMBALI</button>
          <button onClick={nextLetter} className="py-5 bg-rose-600 rounded-[2rem] font-black text-white shadow-xl shadow-rose-100 hover:bg-rose-700 hover:scale-[1.02] active:scale-95 transition-all uppercase tracking-widest text-[9px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
    );
  }

  const currentItem = data[currentIndex];
  const currentItems = Array.isArray(currentItem) ? currentItem : [currentItem];
  const isAdvancedLevel = level.id >= 6;
  const typographyClass = level.id === 8 ? 'quranic-typography' : (isAdvancedLevel ? 'arabic-text text-4xl sm:text-6xl md:text-7xl leading-relaxed' : 'arabic-text text-3xl sm:text-4xl md:text-5xl');

  return (
    <div 
      className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in duration-500 min-h-[70vh] bg-white"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
