      }
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < 5) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;

    const distance = touchStartX.current - touchEndX.current;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe) {
      if (mode === 'SEQUENTIAL') nextLetter();
      else nextReviewPage();
    } else if (isRightSwipe) {
      if (mode === 'SEQUENTIAL') prevLetter();
      else prevReviewPage();
    }
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = level.id >= 4 
        ? `Sebutkan ayat Al-Quran atau perkataan Arab ini dengan makhraj dan tajwid yang sempurna: ${letter}` 
        : `Sebutkan huruf hijaiyah ini dengan makhraj yang jelas: ${letter}`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 400);
  };

  const totalSteps = hasReview ? data.length + 6 : data.length;
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const overallProgress = (currentStep / totalSteps) * 100;

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  const pageTitle = useMemo(() => {
    if (level.id === 5) {
      if (currentIndex <= 8) return `Unit 1: Sukun (Halaman ${currentIndex + 1})`;
      if (currentIndex <= 12) return `Unit 2: Mad Asli (Halaman ${currentIndex - 8})`;
      if (currentIndex === 13) return "Unit 3: Wajib Muttasil";
      if (currentIndex === 14) return "Unit 4: Jaiz Munfasil";
      if (currentIndex === 15) return "Unit 5: Arid Lissukun";
      if (currentIndex === 16) return "Unit 6: Mad Lazim";
      if (currentIndex >= 17 && currentIndex <= 21) return `Unit 7: Sederhana Gabungan (Halaman ${currentIndex - 16})`;
      if (currentIndex >= 22 && currentIndex <= 26) return `Unit 8: Sukar Gabungan (Halaman ${currentIndex - 21})`;
    }
    return level.title;
  }, [level.id, currentIndex]);

  if (isIqra8) {
    const currentWaqaf = (IQRA_8_DATA[currentIndex] as any);
    return (
      <div 
        className="max-w-7xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh] bg-white"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <div className="w-full flex justify-between items-center mb-10">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-colors flex items-center space-x-2 group">
             <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-rose-50 transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
             </div>
             <span className="text-xs font-black uppercase tracking-widest">Batal</span>
          </button>
          <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
             <div className="h-full bg-rose-500 transition-all duration-700 shadow-sm" style={{ width: `${overallProgress}%` }}></div>
          </div>
          <div className="flex flex-col items-end">
            <span className="text-[9px] font-black text-rose-600 uppercase tracking-[0.3em]">Hukum Waqaf</span>
            <span className="text-sm font-bold text-gray-900">{currentStep} / {totalSteps}</span>
          </div>
        </div>

        <div className="w-full flex flex-col items-center space-y-12">
          {/* Rule Header */}
          <div className="w-full max-w-4xl bg-white p-8 rounded-[3rem] shadow-xl shadow-rose-900/5 border border-rose-50 flex flex-col items-center text-center space-y-4">
            <div className="w-20 h-20 bg-rose-600 rounded-[2rem] flex items-center justify-center text-white text-4xl quranic-typography shadow-lg shadow-rose-200 rotate-2">
              {currentWaqaf.sign}
            </div>
            <div className="space-y-1">
              <h2 className="text-2xl font-black text-gray-900 tracking-tight">{currentWaqaf.name}</h2>
              <div className="px-5 py-1.5 bg-rose-50 text-rose-700 text-xs font-bold rounded-full border border-rose-100 italic">
                "{currentWaqaf.rule}"
              </div>
            </div>
          </div>

          {/* 3x1 Layout for Examples with Bigger Text */}
          <div className="w-full space-y-10">
             <div className="flex items-center justify-center space-x-4 opacity-30">
                <div className="h-px w-10 bg-gray-300"></div>
                <span className="text-[9px] font-black uppercase tracking-[0.4em]">Latihan Bacaan</span>
                <div className="h-px w-10 bg-gray-300"></div>
             </div>

             <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6" dir="rtl">
               {currentWaqaf.examples.map((ex: string, idx: number) => (
                 <button 
                   key={idx}
                   onClick={() => handleBoxClick(ex, idx)}
                   disabled={isLoadingAudio}
                   className={`bg-white rounded-[2.5rem] border-2 border-gray-50 shadow-sm p-8 flex items-center justify-center text-center relative group overflow-hidden transition-all duration-500 ${isAnimating === idx ? 'scale-95 border-rose-500 bg-rose-50/20' : 'hover:border-rose-200 hover:shadow-xl hover:-translate-y-1'}`}
                 >
                    <div className="absolute top-0 right-0 w-1 h-full bg-transparent group-hover:bg-rose-500/10 transition-all"></div>
                    <span className="quranic-typography text-3xl sm:text-4xl text-gray-950 select-none block leading-[2.4]">
                      {ex}
                    </span>
                    {isLoadingAudio && isAnimating === idx && (
                      <div className="absolute top-4 left-4">
                        <div className="w-6 h-6 border-3 border-rose-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
                    )}
                 </button>
               ))}
             </div>
          </div>
        </div>

        <div className="w-full max-w-xl grid grid-cols-2 gap-4 mt-16 pb-12">
          <button onClick={prevLetter} disabled={currentIndex === 0} className="py-5 bg-white border-2 border-gray-100 rounded-[2rem] font-black text-gray-400 hover:text-rose-600 hover:border-rose-100 disabled:opacity-20 transition-all uppercase tracking-widest text-[9px]">KEMBALI</button>
          <button onClick={nextLetter} className="py-5 bg-rose-600 rounded-[2rem] font-black text-white shadow-xl shadow-rose-100 hover:bg-rose-700 hover:scale-[1.02] active:scale-95 transition-all uppercase tracking-widest text-[9px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
