  const typographyClass = level.id === 8 ? 'quranic-typography' : (isAdvancedLevel ? 'arabic-text text-4xl sm:text-6xl md:text-7xl leading-relaxed' : 'arabic-text text-3xl sm:text-4xl md:text-5xl');

  return (
    <div 
      className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in duration-500 min-h-[70vh] bg-white"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
