           </div>
           <span className="text-xs font-black uppercase tracking-widest">Batal</span>
        </button>
        <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-700 shadow-sm`} style={{ width: `${overallProgress}%` }}></div>
        </div>
        <div className="flex flex-col items-end">
          <span className={`text-[9px] font-black text-${colorTheme}-600 uppercase tracking-[0.3em]`}>{mode === 'SEQUENTIAL' ? level.title : 'REVIEW'}</span>
          <span className="text-sm font-bold text-gray-900">{currentStep} / {totalSteps}</span>
        </div>
      </div>

      <div className="w-full flex flex-col items-center space-y-10">
        <div className="text-center space-y-4 max-w-2xl">
           <h2 className="text-4xl font-black text-gray-900 tracking-tight">{mode === 'SEQUENTIAL' ? pageTitle : 'Ulangkaji Huruf'}</h2>
           <p className="text-sm text-gray-400 font-medium uppercase tracking-widest">{level.subtitle}</p>
