                className={`w-full bg-white shadow-md border border-gray-100 text-gray-900 flex items-center justify-center transition-all duration-500 relative rounded-[3rem] sm:rounded-[4rem] px-8 py-16 sm:py-24 ${isAnimating === vIdx ? 'scale-95 border-emerald-400 ring-8 ring-emerald-50' : 'hover:scale-[1.02] hover:shadow-2xl hover:border-emerald-200'}`}
              >
