              {reviewGrids[reviewPage]?.map((letter: string, idx: number) => (
                <button
                  key={`${reviewPage}-${idx}`}
                  onClick={() => handleBoxClick(letter, idx)}
                  disabled={isLoadingAudio}
                  className={`aspect-square bg-white rounded-[2rem] shadow-sm flex items-center justify-center transition-all duration-500 border border-transparent hover:border-emerald-300 relative ${isAnimating === idx ? 'scale-90 border-emerald-500 shadow-xl' : 'hover:scale-105 active:scale-95 hover:shadow-lg'}`}
                >
                   {isLoadingAudio && isAnimating === idx && (
                    <div className="absolute top-2 left-2"><div className="w-3 h-3 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div></div>
                  )}
                  <span className={`${typographyClass} font-black text-4xl leading-none text-emerald-950 transition-transform duration-500 select-none ${isAnimating === idx ? 'scale-125' : ''}`}>
                    {letter}
                  </span>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-6 mt-16 pb-12">
        <button onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage} disabled={mode === 'SEQUENTIAL' && currentIndex === 0} className="py-6 bg-white border-2 border-gray-100 rounded-[2.5rem] font-black text-gray-400 hover:text-emerald-600 hover:border-emerald-100 disabled:opacity-20 transition-all uppercase tracking-widest text-[10px]">KEMBALI</button>
        <button onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage} className={`py-6 bg-${colorTheme}-600 rounded-[2.5rem] font-black text-white shadow-2xl shadow-${colorTheme}-100 hover:brightness-110 hover:scale-[1.02] active:scale-95 transition-all uppercase tracking-widest text-[10px]`}>
          {mode === 'SEQUENTIAL' ? (currentIndex === data.length - 1 ? (hasReview ? 'Mula Review' : 'Selesai') : 'SETERUSNYA') : (reviewPage === 5 ? 'SELESAI' : 'SETERUSNYA')}
        </button>
      </div>
      <Copyright />
    </div>
  );
};

