      if (currentIndex === 13) return "Unit 3: Wajib Muttasil";
      if (currentIndex === 14) return "Unit 4: Jaiz Munfasil";
      if (currentIndex === 15) return "Unit 5: Arid Lissukun";
      if (currentIndex === 16) return "Unit 6: Mad Lazim";
      if (currentIndex >= 17 && currentIndex <= 21) return `Unit 7: Sederhana Gabungan (Halaman ${currentIndex - 16})`;
      if (currentIndex >= 22 && currentIndex <= 26) return `Unit 8: Sukar Gabungan (Halaman ${currentIndex - 21})`;
    }
    if (ruleInfo) return ruleInfo.tajuk;
    return level.title;
  }, [level.id, currentIndex, ruleInfo]);

  if (isIqra8) {
    const currentWaqaf = (IQRA_8_DATA[currentIndex] as any);
    return (
      <div 
        className="max-w-7xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh] bg-white"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <div className="w-full flex justify-between items-center mb-10">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-colors flex items-center space-x-2 group">
             <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-rose-50 transition-all">
