                <span className="text-[9px] font-black uppercase tracking-[0.4em]">Latihan Bacaan</span>
                <div className="h-px w-10 bg-gray-300"></div>
             </div>

             <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-6" dir="rtl">
               {currentWaqaf.examples.map((ex: string, idx: number) => (
                 <button 
                   key={idx}
                   onClick={() => handleBoxClick(ex, idx)}
                   disabled={isLoadingAudio}
                   className={`bg-white rounded-[2.5rem] border-2 border-gray-50 shadow-sm p-10 flex items-center justify-center text-center relative group overflow-hidden transition-all duration-500 ${isAnimating === idx ? 'scale-95 border-rose-500 bg-rose-50/20' : 'hover:border-rose-200 hover:shadow-xl hover:-translate-y-1'}`}
                 >
                    <div className="absolute top-0 right-0 w-1.5 h-full bg-transparent group-hover:bg-rose-500/10 transition-all"></div>
                    <span className="quranic-typography text-3xl sm:text-4xl text-gray-950 select-none block leading-[2.4]">
                      {ex}
                    </span>
                    {isLoadingAudio && isAnimating === idx && (
                      <div className="absolute top-4 left-4">
                        <div className="w-6 h-6 border-3 border-rose-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
