import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isIqra1 = level.id === 1;
  const isIqra7 = level.id === 7;
  const isIqra8 = level.id === 8;
  const isJuz30 = level.id === 9;
  const hasReview = level.id >= 1 && level.id <= 4; 

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const touchStartX = useRef<number | null>(0);
  const touchEndX = useRef<number | null>(0);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    if (!hasReview) return [];
    const grids = [];
    let flatPool: string[] = [];
    if (level.id === 1) flatPool = IQRA_1_LETTERS;
    else if (level.id === 2) flatPool = IQRA_2_DATA.flat();
    else if (level.id === 3) flatPool = IQRA_3_DATA.flat();
    else if (level.id === 4) flatPool = [...IQRA_4_DATA.flatMap(g => g.slice(3)), ...IQRA_3_DATA.flat()];

    for (let i = 0; i < 6; i++) {
      grids.push([...flatPool].sort(() => Math.random() - 0.5).slice(0, 16)); 
    }
    return grids;
  }, [level.id, hasReview]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) setCurrentIndex(currentIndex + 1);
    else hasReview ? (setMode('REVIEW'), setReviewPage(0)) : onFinish();
  };

  const prevLetter = () => currentIndex > 0 && setCurrentIndex(currentIndex - 1);
  const nextReviewPage = () => reviewPage < 5 ? setReviewPage(reviewPage + 1) : onFinish();
  const prevReviewPage = () => reviewPage > 0 ? setReviewPage(reviewPage - 1) : (setMode('SEQUENTIAL'), setCurrentIndex(data.length - 1));

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    if (Math.abs(distance) > minSwipeDistance) {
      distance > 0 ? (mode === 'SEQUENTIAL' ? nextLetter() : nextReviewPage()) : (mode === 'SEQUENTIAL' ? prevLetter() : prevReviewPage());
    }
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Sebutkan ayat atau huruf ini dengan makhraj yang tepat: ${letter}`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) { console.error(e); } finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 400);
  };

  // Define dynamic content info for IQRA 7 & 8 and Juz 30
  const contentInfo = useMemo(() => {
    if (isIqra7) {
      if (currentIndex <= 5) return { tajuk: 'Izhar Halqi', cara: 'Jelas & Nyata (Tanpa Dengung)', huruf: 'ء هـ ع ح غ خ' };
      if (currentIndex <= 7) return { tajuk: 'Idgham Ma\'al Ghunnah', cara: 'Masuk serta Dengung', huruf: 'ي ن م و' };
      if (currentIndex === 8) return { tajuk: 'Idgham Bila Ghunnah', cara: 'Masuk tanpa Dengung', huruf: 'ل ر' };
      if (currentIndex === 9) return { tajuk: 'Iqlab', cara: 'Tukar suara Nun/Tanwin kepada Mim', huruf: 'ب' };
      if (currentIndex <= 11) return { tajuk: 'Ikhfa\' Haqiqi', cara: 'Samar-samar (Sembunyi)', huruf: 'ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك' };
      if (currentIndex <= 21) return { tajuk: 'Latihan Campuran', cara: 'Pelbagai Hukum Tajwid', huruf: 'Hukum-hukum Nun Mati' };
      if (currentIndex === 22) return { tajuk: 'Ikhfa\' Syafawi', cara: 'Sembunyi suara Mim bertemu Ba', huruf: 'Mim Mati + ب' };
      if (currentIndex === 23) return { tajuk: 'Idgham Mimi', cara: 'Masuk suara Mim bertemu Mim', huruf: 'Mim Mati + م' };
      if (currentIndex <= 25) return { tajuk: 'Izhar Syafawi', cara: 'Jelas suara Mim (Tanpa Dengung)', huruf: 'Mim Mati + Selain م/ب' };
      return { tajuk: 'Latihan Ayat Panjang', cara: 'Latihan Fasahah & Tajwid', huruf: 'Makhraj & Tajwid' };
    }
    if (isIqra8) {
      const waqaf = (IQRA_8_DATA[currentIndex] as any);
      return { tajuk: waqaf.name, huruf: waqaf.sign };
    }
    if (isJuz30) {
      const entry = (JUZ_30_DATA[currentIndex] as any);
      return { tajuk: `Surah ${entry.surah}`, verse: entry.verse, next: entry.nextVerse };
    }
    return null;
  }, [isIqra7, isIqra8, isJuz30, currentIndex]);

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 9: return 'amber';
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const totalSteps = hasReview ? data.length + 6 : data.length;
  const progress = (currentStep / totalSteps) * 100;

  // Handle Juz 30 Rendering
  if (isJuz30) {
    const entry = JUZ_30_DATA[currentIndex];
    return (
      <div className="max-w-7xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchEnd={onTouchEnd}>
        <div className="w-full flex justify-between items-center mb-10">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-amber-600 transition-colors flex items-center space-x-2 group">
             <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-amber-50 transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
             </div>
             <span className="text-xs font-black uppercase tracking-widest">Batal</span>
          </button>
          <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
             <div className="h-full bg-amber-500 transition-all duration-700" style={{ width: `${progress}%` }}></div>
          </div>
          <div className="flex flex-col items-end">
            <span className="text-[10px] font-black text-amber-600 uppercase tracking-widest">JUZ 30</span>
            <span className="text-sm font-bold text-gray-900">{currentStep}/{totalSteps}</span>
          </div>
        </div>

        <div className="w-full max-w-4xl flex flex-col items-center space-y-12">
          {/* Tajuk Section */}
          <div className="text-center space-y-4">
            <h2 className="text-4xl font-black text-gray-900 tracking-tight">Surah {entry.surah}</h2>
            <div className="inline-block px-4 py-1 bg-amber-50 text-amber-600 text-[10px] font-black uppercase tracking-widest rounded-full border border-amber-100">
               Hafazan Lazim
            </div>
          </div>

          {/* Main Content Box */}
          <button 
            onClick={() => handleBoxClick(entry.verse, 'verse')}
            className={`w-full bg-white p-12 sm:p-20 rounded-[4rem] shadow-2xl shadow-amber-900/10 border-4 border-gray-50 flex flex-col items-center text-center transition-all duration-500 hover:border-amber-200 ${isAnimating === 'verse' ? 'scale-95 border-amber-400' : ''}`}
          >
            <span className="quranic-typography text-4xl sm:text-6xl text-gray-950 leading-loose">
              {entry.verse}
            </span>
            {isLoadingAudio && isAnimating === 'verse' && (
              <div className="mt-8 w-10 h-10 border-4 border-amber-500 border-t-transparent rounded-full animate-spin"></div>
            )}
          </button>

          {/* Sambungan Section */}
          <div className="w-full flex flex-col items-center space-y-4 pt-10">
             <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em]">SAMBUNGAN AYAT</span>
             <div className="w-full max-w-2xl bg-amber-50/50 p-8 rounded-[3rem] border-2 border-dashed border-amber-200 text-center">
                <span className="quranic-typography text-2xl sm:text-3xl text-amber-700 opacity-80 italic">
                  {entry.nextVerse}...
                </span>
             </div>
          </div>
        </div>

        <div className="w-full max-w-xl grid grid-cols-2 gap-6 mt-16 pb-12">
          <button onClick={prevLetter} className="py-6 bg-white border-2 border-gray-100 rounded-3xl font-black text-gray-400 hover:text-amber-600 uppercase tracking-widest text-[10px]">KEMBALI</button>
          <button onClick={nextLetter} className="py-6 bg-amber-600 rounded-3xl font-black text-white shadow-xl hover:brightness-110 transition-all uppercase tracking-widest text-[10px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
    );
  }

  // Handle IQRA 1-8
  const currentItems = Array.isArray(data[currentIndex]) ? data[currentIndex] : [data[currentIndex]];
  const isLargeFocus = isIqra1;
  const isAdvanced = level.id >= 5;

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchEnd={onTouchEnd}>
      <div className="w-full flex justify-between items-center mb-10">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-2`}>
