            </div>
            <div className="flex flex-col items-center">
              <span className={`text-[10px] font-black text-${colorTheme}-500 uppercase tracking-widest`}>HURUF TERLIBAT</span>
              <span className={`text-3xl font-bold text-${colorTheme}-600 quranic-typography mt-1`}>{contentInfo.huruf}</span>
