import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA, BISMILLAH, Surah } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isIqra1 = level.id === 1;
  const isIqra7 = level.id === 7;
  const isIqra8 = level.id === 8;
  const isJuz30 = level.id === 9;
  const hasReview = level.id >= 1 && level.id <= 4; 

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  // Juz 30 Specific State
  const [selectedSurahIndex, setSelectedSurahIndex] = useState<number | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const touchStartX = useRef<number | null>(0);
  const touchEndX = useRef<number | null>(0);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    if (!hasReview) return [];
    const grids = [];
    let flatPool: string[] = [];
    if (level.id === 1) flatPool = IQRA_1_LETTERS;
    else if (level.id === 2) flatPool = IQRA_2_DATA.flat();
    else if (level.id === 3) flatPool = IQRA_3_DATA.flat();
    else if (level.id === 4) flatPool = [...IQRA_4_DATA.flatMap(g => g.slice(3)), ...IQRA_3_DATA.flat()];

    for (let i = 0; i < 6; i++) {
      grids.push([...flatPool].sort(() => Math.random() - 0.5).slice(0, 16)); 
    }
    return grids;
  }, [level.id, hasReview]);

  const nextItem = () => {
    if (currentIndex < data.length - 1) setCurrentIndex(currentIndex + 1);
    else hasReview ? (setMode('REVIEW'), setReviewPage(0)) : onFinish();
  };

  const prevItem = () => currentIndex > 0 && setCurrentIndex(currentIndex - 1);

  const nextReviewPage = () => reviewPage < 5 ? setReviewPage(reviewPage + 1) : onFinish();
  const prevReviewPage = () => reviewPage > 0 ? setReviewPage(reviewPage - 1) : (setMode('SEQUENTIAL'), setCurrentIndex(data.length - 1));

  // Swiping for Juz 30 Surah pages
  const handleSurahNext = () => {
    if (selectedSurahIndex !== null && selectedSurahIndex < JUZ_30_DATA.length - 1) {
      setSelectedSurahIndex(selectedSurahIndex + 1);
    }
  };

  const handleSurahBack = () => {
    if (selectedSurahIndex !== null && selectedSurahIndex > 0) {
      setSelectedSurahIndex(selectedSurahIndex - 1);
    } else {
      setSelectedSurahIndex(null);
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    const isSignificant = Math.abs(distance) > minSwipeDistance;

    if (isSignificant) {
      if (isJuz30 && selectedSurahIndex !== null) {
        // Swipe Right to go Next Surah (Gesture from right to left)
        if (distance > 0) handleSurahNext();
        // Swipe Left to go back (Gesture from left to right)
        else handleSurahBack();
      } else {
        // Default sequential navigation
        if (distance > 0) {
          mode === 'SEQUENTIAL' ? nextItem() : nextReviewPage();
        } else {
          mode === 'SEQUENTIAL' ? prevItem() : prevReviewPage();
        }
      }
    }
    touchStartX.current = null;
    touchEndX.current = null;
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Sebutkan ayat atau huruf ini dengan makhraj yang tepat: ${letter}`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) { console.error(e); } finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 400);
  };

  const contentInfo = useMemo(() => {
    if (isIqra7) {
      if (currentIndex <= 5) return { tajuk: 'Izhar Halqi', cara: 'Jelas & Nyata (Tanpa Dengung)', huruf: 'ء هـ ع ح غ خ' };
      if (currentIndex <= 7) return { tajuk: 'Idgham Ma\'al Ghunnah', cara: 'Masuk serta Dengung (2 Harakat)', huruf: 'ي ن م و' };
      if (currentIndex === 8) return { tajuk: 'Idgham Bila Ghunnah', cara: 'Masuk tanpa Dengung', huruf: 'ل ر' };
      if (currentIndex === 9) return { tajuk: 'Iqlab', cara: 'Tukar suara Nun/Tanwin kepada Mim (Dengung)', huruf: 'ب' };
      if (currentIndex <= 11) return { tajuk: 'Ikhfa\' Haqiqi', cara: 'Samar-samar (Sembunyi) serta Dengung', huruf: 'ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك' };
      if (currentIndex <= 21) return { tajuk: 'Latihan Campuran', cara: 'Kenalpasti Hukum Nun Mati', huruf: 'Hukum-hukum Nun Mati' };
      if (currentIndex === 22) return { tajuk: 'Ikhfa\' Syafawi', cara: 'Sembunyi suara Mim bertemu Ba (Dengung)', huruf: 'Mim Mati + ب' };
      if (currentIndex === 23) return { tajuk: 'Idgham Mimi', cara: 'Masuk suara Mim bertemu Mim (Dengung)', huruf: 'Mim Mati + م' };
      if (currentIndex <= 25) return { tajuk: 'Izhar Syafawi', cara: 'Jelas suara Mim (Tanpa Dengung)', huruf: 'Mim Mati + Selain م/ب' };
      return { tajuk: 'Latihan Ayat Panjang', cara: 'Latihan Fasahah & Tajwid', huruf: 'Makhraj & Tajwid' };
    }
    return null;
  }, [isIqra7, currentIndex]);

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 9: return 'amber';
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const totalSteps = hasReview ? data.length + 6 : data.length;
  const progress = (currentStep / totalSteps) * 100;

  // Juz 30 - Menu or Surah Page
  if (isJuz30) {
    if (selectedSurahIndex === null) {
      return (
        <div className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
          <div className="w-full flex justify-between items-center mb-10">
             <button onClick={onBack} className="p-3 bg-white border border-gray-100 shadow-sm rounded-2xl hover:bg-gray-50 text-amber-600 transition-all flex items-center space-x-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
                <span className="text-xs font-black uppercase tracking-widest">Kembali</span>
             </button>
             <h2 className="text-3xl font-black text-gray-900 tracking-tight">Pilih Surah</h2>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 w-full pb-20">
            {JUZ_30_DATA.map((surah, idx) => (
              <button 
                key={surah.id}
                onClick={() => setSelectedSurahIndex(idx)}
                className="p-8 bg-white border-2 border-gray-50 rounded-[2.5rem] shadow-sm hover:shadow-xl hover:-translate-y-2 hover:border-amber-200 transition-all text-left flex items-center space-x-6 group"
              >
                <div className="w-14 h-14 bg-amber-500 rounded-2xl flex items-center justify-center text-white font-black text-lg group-hover:scale-110 transition-transform">
                  {idx + 1}
                </div>
                <div className="flex-1">
                   <h3 className="text-xl font-black text-[#1B1C57]">Surah {surah.name}</h3>
                   <p className="text-xs font-bold text-amber-600 uppercase tracking-widest mt-1">{surah.verses.length} Ayat</p>
                </div>
                <div className="text-amber-100 opacity-0 group-hover:opacity-100 transition-opacity">
                   <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10.293 3.293a1 1 0 011.414 0l6 6a1 1 0 010 1.414l-6 6a1 1 0 01-1.414-1.414L14.586 11H3a1 1 0 110-2h11.586l-4.293-4.293a1 1 0 010-1.414z" clipRule="evenodd"/></svg>
                </div>
              </button>
            ))}
          </div>
          <Copyright />
        </div>
      );
    }

    const surah = JUZ_30_DATA[selectedSurahIndex];
    return (
      <div className="max-w-7xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
         <div className="w-full flex justify-between items-center mb-8 sticky top-0 bg-white/80 backdrop-blur-md z-30 py-2">
            <button onClick={() => setSelectedSurahIndex(null)} className="p-3 bg-white border border-gray-100 shadow-sm rounded-2xl hover:bg-amber-50 text-amber-600 transition-all flex items-center space-x-2">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
               <span className="text-xs font-black uppercase tracking-widest">Menu</span>
            </button>
            <div className="text-center">
               <h2 className="text-3xl font-black text-gray-900 leading-none">Surah {surah.name}</h2>
               <div className="mt-2 flex items-center justify-center space-x-2">
                  <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Surah {selectedSurahIndex + 1} dari {JUZ_30_DATA.length}</span>
               </div>
            </div>
            <div className="text-right">
              <span className="text-xs font-bold text-gray-400">Swipe Kanan untuk Next</span>
            </div>
         </div>

         {/* Full Surah Scrolling Reading View */}
         <div className="w-full max-w-5xl flex-1 overflow-y-auto px-4 pb-20 custom-scrollbar">
            <div className="w-full bg-white p-10 sm:p-20 rounded-[4rem] shadow-2xl border-4 border-gray-50 flex flex-col items-center min-h-[70vh]">
               {/* Bismillah */}
               <div className="mb-20 text-center animate-in fade-in duration-1000">
                  <span className="quranic-typography text-4xl sm:text-6xl text-gray-300 opacity-60 italic">
                     {BISMILLAH}
                  </span>
               </div>

               {/* Verses Container */}
               <div className="flex flex-wrap justify-center gap-x-12 gap-y-16" dir="rtl">
                  {surah.verses.map((v, i) => (
                     <div key={i} className="flex flex-col items-center group">
                        <button 
                          onClick={() => handleBoxClick(v, i)}
                          className={`flex items-center space-x-6 space-x-reverse transition-all duration-500 py-4 px-8 rounded-3xl ${isAnimating === i ? 'bg-amber-50 scale-105' : 'hover:bg-gray-50'}`}
                        >
                           <span className="quranic-typography text-3xl sm:text-5xl text-gray-950 leading-[2.8] text-right">
                              {v}
                           </span>
                           <div className="w-12 h-12 flex-shrink-0 rounded-full border-2 border-amber-200 flex items-center justify-center text-xs font-black text-amber-500 shadow-sm transition-colors group-hover:bg-amber-500 group-hover:text-white group-hover:border-amber-500 translate-y-3">
                              {i + 1}
                           </div>
                        </button>

                        {/* Sambungan Logic Tip */}
                        {i < surah.verses.length - 1 && (
                          <div className="w-full h-px bg-gradient-to-l from-transparent via-gray-100 to-transparent mt-4 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                        )}
                     </div>
                  ))}
               </div>

               {/* Completion Reward Indicator */}
               <div className="mt-24 flex flex-col items-center space-y-6 pt-12 border-t border-gray-50 w-full">
                  <div className="w-20 h-20 bg-amber-50 rounded-full flex items-center justify-center text-4xl animate-bounce shadow-inner">
                    ✨
                  </div>
                  <div className="text-center space-y-2">
                    <h4 className="text-xl font-black text-gray-900">Alhamdulillah!</h4>
                    <p className="text-sm text-gray-500 max-w-xs mx-auto font-medium">Selesaikan bacaan anda dan swipe ke surah seterusnya.</p>
                  </div>
               </div>
            </div>
         </div>

         {/* Navigation Overlay Hints */}
         <div className="w-full max-w-xl grid grid-cols-2 gap-6 pt-10 pb-8 sticky bottom-0 bg-white/80 backdrop-blur-md">
            <button 
              onClick={handleSurahBack} 
              className="py-6 bg-white border-2 border-gray-100 rounded-3xl font-black text-gray-400 hover:text-amber-600 transition-all uppercase tracking-widest text-[10px] shadow-sm flex items-center justify-center space-x-3"
            >
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 19l-7-7 7-7"/></svg>
               <span>SEBELUMNYA</span>
            </button>
            <button 
              onClick={handleSurahNext} 
              disabled={selectedSurahIndex === JUZ_30_DATA.length - 1}
              className="py-6 bg-amber-600 rounded-3xl font-black text-white shadow-xl hover:brightness-110 transition-all uppercase tracking-widest text-[10px] flex items-center justify-center space-x-3 disabled:opacity-20"
            >
               <span>SETERUSNYA</span>
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7"/></svg>
            </button>
         </div>
         <Copyright />
      </div>
    );
  }

  // Handle IQRA 1-8
  const currentItems = Array.isArray(data[currentIndex]) ? data[currentIndex] : [data[currentIndex]];
  const isLargeFocus = isIqra1;
  const isAdvanced = level.id >= 5;

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
      <div className="w-full flex justify-between items-center mb-10">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-2`}>
           <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center hover:bg-emerald-50"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg></div>
           <span className="text-xs font-black uppercase tracking-widest">Batal</span>
        </button>
        <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-500`} style={{ width: `${progress}%` }}></div>
        </div>
        <div className="text-right">
          <span className={`text-[10px] font-black text-${colorTheme}-600 uppercase tracking-widest`}>{mode === 'SEQUENTIAL' ? (contentInfo?.tajuk || level.title) : 'REVIEW'}</span>
          <p className="text-sm font-bold text-gray-900">{currentStep}/{totalSteps}</p>
        </div>
      </div>

      <div className="w-full flex flex-col items-center space-y-10 flex-1 justify-center">
        {mode === 'SEQUENTIAL' && contentInfo && (
          <div className="text-center space-y-4 animate-in slide-in-from-top-4">
            <div className="space-y-1">
              <h2 className="text-3xl font-black text-gray-900">{contentInfo.tajuk}</h2>
              {isIqra7 && (
                <div className="flex flex-col items-center space-y-1 mt-2">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Cara Bacaan</span>
                  <p className={`text-sm font-black text-${colorTheme}-600 uppercase tracking-widest italic bg-${colorTheme}-50 px-6 py-2 rounded-full border border-${colorTheme}-100 shadow-sm`}>
                    {contentInfo.cara}
                  </p>
                </div>
              )}
            </div>
            <div className="flex flex-col items-center pt-2">
              <span className={`text-[10px] font-black text-${colorTheme}-500 uppercase tracking-widest`}>HURUF TERLIBAT</span>
              <span className={`text-4xl font-bold text-${colorTheme}-600 quranic-typography mt-1 drop-shadow-sm`}>{contentInfo.huruf}</span>
            </div>
          </div>
        )}

        {mode === 'SEQUENTIAL' && !contentInfo && (
          <div className="text-center space-y-2 animate-in slide-in-from-top-4">
            <h2 className="text-4xl font-black text-gray-900">{level.title}</h2>
            <p className="text-sm text-gray-400 font-bold uppercase tracking-widest">{level.subtitle}</p>
          </div>
        )}

        <div className={`w-full grid gap-8 ${isLargeFocus ? 'grid-cols-1 max-w-lg' : (level.id >= 4 ? 'grid-cols-1 max-w-4xl' : 'grid-cols-2 sm:grid-cols-3 max-w-5xl')}`} dir="rtl">
          {mode === 'SEQUENTIAL' ? currentItems.map((word: string, idx: number) => (
            <button 
              key={idx} 
              onClick={() => handleBoxClick(word, idx)}
              className={`w-full bg-white shadow-xl border-4 border-gray-50 rounded-[4rem] flex items-center justify-center p-12 transition-all duration-500 relative group ${isAnimating === idx ? 'scale-95 border-emerald-400 bg-emerald-50/30 shadow-inner' : 'hover:scale-105 hover:shadow-2xl hover:border-emerald-100'}`}
            >
              <span className={`arabic-text font-black text-center transition-transform duration-500 select-none ${isLargeFocus ? 'text-[12rem] sm:text-[16rem] leading-none' : (isAdvanced ? 'text-5xl sm:text-6xl' : 'text-6xl sm:text-8xl')}`}>
                {word}
              </span>
              {isLoadingAudio && isAnimating === idx && (
                <div className="absolute top-10 left-10 w-10 h-10 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
              )}
            </button>
          )) : (
            <div className="col-span-full grid grid-cols-4 gap-6 w-full max-w-4xl p-10 bg-emerald-50 rounded-[4rem] border-2 border-emerald-100 animate-in zoom-in-95">
              {reviewGrids[reviewPage].map((letter: string, idx: number) => (
                <button 
                  key={idx} 
                  onClick={() => handleBoxClick(letter, idx)}
                  className={`aspect-square bg-white rounded-3xl flex items-center justify-center text-5xl font-black transition-all hover:scale-110 active:scale-90 border-2 border-transparent shadow-sm hover:border-emerald-300 ${isAnimating === idx ? 'scale-90 border-emerald-500 shadow-xl' : ''}`}
                >
                  <span className="arabic-text">{letter}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-6 mt-16 pb-12">
        <button onClick={mode === 'SEQUENTIAL' ? prevItem : prevReviewPage} disabled={mode === 'SEQUENTIAL' && currentIndex === 0} className="py-6 bg-white border-2 border-gray-100 rounded-3xl font-black text-gray-400 hover:text-emerald-600 transition-all uppercase tracking-widest text-[10px] shadow-sm">KEMBALI</button>
        <button onClick={mode === 'SEQUENTIAL' ? nextItem : nextReviewPage} className={`py-6 bg-${colorTheme}-600 rounded-3xl font-black text-white shadow-xl hover:brightness-110 transition-all uppercase tracking-widest text-[10px]`}>
          {mode === 'SEQUENTIAL' ? (currentIndex === data.length - 1 ? (hasReview ? 'ULANGKAJI' : 'SELESAI') : 'SETERUSNYA') : (reviewPage === 5 ? 'SELESAI' : 'SETERUSNYA')}
        </button>
      </div>
      <Copyright />
    </div>
  );
};

export default PracticeSession;

import React, { useState, useRef } from 'react';
import Copyright from './Copyright';
import { User } from '../types';

interface ProfileSetupProps {
  onComplete: (user: User) => void;
}

const AVATARS = [
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Fatima&top[]=hijab&accessory[]=round&clothing=graphicShirt&clothingColor=blue01',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Zahra&top[]=hijab&clothing=collarAndSweater&clothingColor=pink02',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Aisha&top[]=hijab&clothing=shirtVNeck&clothingColor=emerald',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Omar&top[]=turban&clothing=hoodie&clothingColor=green03&facialHairProbability=0',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Ali&top[]=shortHair&clothing=graphicShirt&clothingColor=red&facialHairProbability=0',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Bilal&top[]=turban&clothing=overall&clothingColor=blue03&facialHairProbability=0'
];

const ProfileSetup: React.FC<ProfileSetupProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    name: '',
    age: '',
    parentEmail: '',
    photoURL: AVATARS[0]
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleNext = () => setStep(s => s + 1);
  const handleBack = () => setStep(s => s - 1);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onComplete({
      name: formData.name,
      email: 'pelajar@advancekids.com', 
      age: parseInt(formData.age) || 0,
      parentEmail: formData.parentEmail,
      photoURL: formData.photoURL,
      isProfileComplete: true
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, photoURL: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
      <div className="max-w-xl w-full bg-white rounded-[3.5rem] shadow-2xl overflow-hidden flex flex-col p-10 border border-emerald-50">

        <div className="flex justify-between items-center mb-10 px-4">
          {[1, 2, 3].map(i => (
            <div key={i} className="flex items-center flex-1 last:flex-none">
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black transition-all duration-500 shadow-sm ${step >= i ? 'bg-emerald-600 text-white scale-110' : 'bg-emerald-50 text-emerald-300'}`}>
                {i}
              </div>
              {i < 3 && <div className={`h-1 flex-1 mx-3 rounded-full transition-colors duration-500 ${step > i ? 'bg-emerald-600' : 'bg-emerald-50'}`}></div>}
            </div>
          ))}
        </div>

        {step === 1 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-8 duration-500">
            <div className="space-y-2">
              <h2 className="text-4xl font-black text-gray-900 tracking-tight">Kenali Anda 🌟</h2>
              <p className="text-gray-500 font-medium">Siapakah nama pelajar hebat hari ini?</p>
            </div>
            <div className="space-y-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest ml-1">Nama Penuh</label>
                <input 
                  type="text" 
                  autoFocus
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full px-8 py-5 bg-emerald-50/30 rounded-[2rem] border-2 border-transparent focus:border-emerald-400 focus:bg-white outline-none transition-all text-lg font-bold shadow-inner"
                  placeholder="Contoh: Ahmad Al-Fatih"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest ml-1">Umur (Tahun)</label>
                <input 
                  type="number" 
                  value={formData.age}
                  onChange={e => setFormData({...formData, age: e.target.value})}
                  className="w-full px-8 py-5 bg-emerald-50/30 rounded-[2rem] border-2 border-transparent focus:border-emerald-400 focus:bg-white outline-none transition-all text-lg font-bold shadow-inner"
                  placeholder="Contoh: 7"
                />
              </div>
            </div>
            <button 
              disabled={!formData.name || !formData.age}
              onClick={handleNext}
              className="w-full py-6 bg-emerald-600 text-white rounded-[2rem] font-black text-lg shadow-xl shadow-emerald-200/50 disabled:opacity-50 transition-all hover:scale-[1.02] active:scale-95 mt-4"
            >
              Seterusnya
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-8 duration-500">
            <div className="space-y-2">
              <h2 className="text-4xl font-black text-gray-900 tracking-tight">Email Waris 📧</h2>
              <p className="text-gray-500 font-medium">Ibu atau bapa akan menerima laporan kemajuan anda.</p>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest ml-1">Email Ibu/Bapa</label>
              <input 
                type="email" 
                autoFocus
                value={formData.parentEmail}
                onChange={e => setFormData({...formData, parentEmail: e.target.value})}
                className="w-full px-8 py-5 bg-emerald-50/30 rounded-[2rem] border-2 border-transparent focus:border-emerald-400 focus:bg-white outline-none transition-all text-lg font-bold shadow-inner"
                placeholder="ibu.ayah@email.com"
              />
            </div>
            <div className="flex space-x-4 mt-4">
              <button onClick={handleBack} className="flex-1 py-6 bg-gray-100 text-gray-500 rounded-[2rem] font-bold transition-all hover:bg-gray-200">Kembali</button>
              <button 
                disabled={!formData.parentEmail.includes('@')}
                onClick={handleNext}
                className="flex-[2] py-6 bg-emerald-600 text-white rounded-[2rem] font-black text-lg shadow-xl shadow-emerald-200/50 disabled:opacity-50 transition-all hover:scale-[1.02] active:scale-95"
              >
                Hampir Siap!
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-8 animate-in fade-in slide-in-from-right-8 duration-500">
            <div className="space-y-2">
              <h2 className="text-4xl font-black text-gray-900 tracking-tight">Pilih Karakter 🎨</h2>
              <p className="text-gray-500 font-medium">Pilih karakter yang paling mewakili anda.</p>
            </div>

            <div className="grid grid-cols-3 gap-4">
              {AVATARS.map((url, idx) => (
                <button 
                  key={idx}
                  onClick={() => setFormData({...formData, photoURL: url})}
                  className={`aspect-square rounded-3xl border-4 transition-all p-2 ${formData.photoURL === url ? 'border-emerald-500 bg-emerald-50' : 'border-gray-100 hover:border-emerald-200'}`}
                >
                  <img src={url} alt="avatar" className="w-full h-full object-cover rounded-2xl" />
                </button>
              ))}
            </div>

            <div className="text-center">
              <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="text-sm font-bold text-emerald-600 hover:underline"
              >
                Atau muat naik foto sendiri 📸
              </button>
            </div>

            <div className="flex space-x-4 mt-4">
              <button onClick={handleBack} className="flex-1 py-6 bg-gray-100 text-gray-500 rounded-[2rem] font-bold transition-all hover:bg-gray-200">Kembali</button>
              <button 
                onClick={handleSubmit}
                className="flex-[2] py-6 bg-emerald-600 text-white rounded-[2rem] font-black text-lg shadow-xl shadow-emerald-200/50 transition-all hover:scale-[1.02] active:scale-95"
              >
                Jom Mula!
              </button>
            </div>
          </div>
        )}
      </div>
      <Copyright />
    </div>
  );
};

export default ProfileSetup;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA, BISMILLAH, Surah } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isIqra1 = level.id === 1;
  const isIqra7 = level.id === 7;
  const isIqra8 = level.id === 8;
  const isJuz30 = level.id === 9;
  const hasReview = level.id >= 1 && level.id <= 4; 

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW'>('SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  // Juz 30 Specific State
  const [selectedSurahIndex, setSelectedSurahIndex] = useState<number | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const reviewGrids = useMemo(() => {
    if (!hasReview) return [];
    const grids = [];
    let flatPool: string[] = [];
    if (level.id === 1) flatPool = IQRA_1_LETTERS;
    else if (level.id === 2) flatPool = IQRA_2_DATA.flat();
    else if (level.id === 3) flatPool = IQRA_3_DATA.flat();
    else if (level.id === 4) flatPool = [...IQRA_4_DATA.flatMap(g => g.slice(3)), ...IQRA_3_DATA.flat()];

    for (let i = 0; i < 6; i++) {
      grids.push([...flatPool].sort(() => Math.random() - 0.5).slice(0, 16)); 
    }
    return grids;
  }, [level.id, hasReview]);

  const nextItem = () => {
    if (currentIndex < data.length - 1) setCurrentIndex(currentIndex + 1);
    else hasReview ? (setMode('REVIEW'), setReviewPage(0)) : onFinish();
  };

  const prevItem = () => currentIndex > 0 && setCurrentIndex(currentIndex - 1);

  const nextReviewPage = () => reviewPage < 5 ? setReviewPage(reviewPage + 1) : onFinish();
  const prevReviewPage = () => reviewPage > 0 ? setReviewPage(reviewPage - 1) : (setMode('SEQUENTIAL'), setCurrentIndex(data.length - 1));

  // Swiping for Juz 30 Surah pages
  const handleSurahNext = () => {
    if (selectedSurahIndex !== null && selectedSurahIndex < JUZ_30_DATA.length - 1) {
      setSelectedSurahIndex(selectedSurahIndex + 1);
    }
  };

  const handleSurahBack = () => {
    if (selectedSurahIndex !== null && selectedSurahIndex > 0) {
      setSelectedSurahIndex(selectedSurahIndex - 1);
    } else {
      setSelectedSurahIndex(null);
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    const isSignificant = Math.abs(distance) > minSwipeDistance;

    if (isSignificant) {
      if (isJuz30 && selectedSurahIndex !== null) {
        // PER USER REQUEST: Swipe Right (Distance < 0) for Next, Swipe Left (Distance > 0) for Back
        if (distance < 0) handleSurahNext();
        else handleSurahBack();
      } else {
        // PER USER REQUEST: Swipe Right (Distance < 0) for Next, Swipe Left (Distance > 0) for Back
        if (distance < 0) {
          mode === 'SEQUENTIAL' ? nextItem() : nextReviewPage();
        } else {
          mode === 'SEQUENTIAL' ? prevItem() : prevReviewPage();
        }
      }
    }
    touchStartX.current = null;
    touchEndX.current = null;
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Sebutkan ayat atau huruf ini dengan makhraj yang tepat: ${letter}`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) { console.error(e); } finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (letter: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(letter);
    setTimeout(() => setIsAnimating(null), 400);
  };

  const contentInfo = useMemo(() => {
    if (isIqra7) {
      if (currentIndex <= 5) return { tajuk: 'Izhar Halqi', cara: 'Jelas & Nyata (Tanpa Dengung)', huruf: 'ء هـ ع ح غ خ' };
      if (currentIndex <= 7) return { tajuk: 'Idgham Ma\'al Ghunnah', cara: 'Masuk serta Dengung (2 Harakat)', huruf: 'ي ن م و' };
      if (currentIndex === 8) return { tajuk: 'Idgham Bila Ghunnah', cara: 'Masuk tanpa Dengung', huruf: 'ل ر' };
      if (currentIndex === 9) return { tajuk: 'Iqlab', cara: 'Tukar suara Nun/Tanwin kepada Mim (Dengung)', huruf: 'ب' };
      if (currentIndex <= 11) return { tajuk: 'Ikhfa\' Haqiqi', cara: 'Samar-samar (Sembunyi) serta Dengung', huruf: 'ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك' };
      if (currentIndex <= 21) return { tajuk: 'Latihan Campuran', cara: 'Kenalpasti Hukum Nun Mati', huruf: 'Hukum-hukum Nun Mati' };
      if (currentIndex === 22) return { tajuk: 'Ikhfa\' Syafawi', cara: 'Sembunyi suara Mim bertemu Ba (Dengung)', huruf: 'Mim Mati + ب' };
      if (currentIndex === 23) return { tajuk: 'Idgham Mimi', cara: 'Masuk suara Mim bertemu Mim (Dengung)', huruf: 'Mim Mati + م' };
      if (currentIndex <= 25) return { tajuk: 'Izhar Syafawi', cara: 'Jelas suara Mim (Tanpa Dengung)', huruf: 'Mim Mati + Selain م/ب' };
      return { tajuk: 'Latihan Ayat Panjang', cara: 'Latihan Fasahah & Tajwid', huruf: 'Makhraj & Tajwid' };
    }
    return null;
  }, [isIqra7, currentIndex]);

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 9: return 'amber';
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : data.length + reviewPage + 1;
  const totalSteps = hasReview ? data.length + 6 : data.length;
  const progress = (currentStep / totalSteps) * 100;

  // Handle Juz 30 Reading
  if (isJuz30) {
    if (selectedSurahIndex === null) {
      return (
        <div className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
          <div className="w-full flex justify-between items-center mb-10">
             <button onClick={onBack} className="p-3 bg-white border border-gray-100 shadow-sm rounded-2xl hover:bg-gray-50 text-amber-600 transition-all flex items-center space-x-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
                <span className="text-xs font-black uppercase tracking-widest">Utama</span>
             </button>
             <h2 className="text-3xl font-black text-gray-900 tracking-tight">Pilih Surah</h2>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 w-full pb-20">
            {JUZ_30_DATA.map((surah, idx) => (
              <button 
                key={surah.id}
                onClick={() => setSelectedSurahIndex(idx)}
                className="p-8 bg-white border-2 border-gray-50 rounded-[2.5rem] shadow-sm hover:shadow-xl hover:-translate-y-2 hover:border-amber-200 transition-all text-left flex items-center space-x-6 group"
              >
                <div className="w-14 h-14 bg-amber-500 rounded-2xl flex items-center justify-center text-white font-black text-lg group-hover:scale-110 transition-transform">
                  {surah.id}
                </div>
                <div className="flex-1">
                   <h3 className="text-xl font-black text-[#1B1C57]">Surah {surah.name}</h3>
                   <p className="text-xs font-bold text-amber-600 uppercase tracking-widest mt-1">{surah.verses.length} Ayat</p>
                </div>
              </button>
            ))}
          </div>
          <Copyright />
        </div>
      );
    }

    const surah = JUZ_30_DATA[selectedSurahIndex];
    return (
      <div className="max-w-7xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
         <div className="w-full flex justify-between items-center mb-10 sticky top-0 bg-white/90 backdrop-blur-md z-30 py-2">
            <button onClick={() => setSelectedSurahIndex(null)} className="p-3 bg-white border border-gray-100 shadow-sm rounded-2xl hover:bg-amber-50 text-amber-600 transition-all flex items-center space-x-2">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
               <span className="text-xs font-black uppercase tracking-widest">Menu</span>
            </button>
            <div className="text-center">
               <h2 className="text-3xl font-black text-gray-900 leading-none">Surah {surah.name}</h2>
               <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest mt-1 inline-block">Surah {selectedSurahIndex + 1} dari {JUZ_30_DATA.length}</span>
            </div>
            <div className="text-right">
               <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Swipe Kanan: Next</p>
            </div>
         </div>

         <div className="w-full max-w-5xl flex-1 overflow-y-auto px-4 pb-20 custom-scrollbar">
            <div className="w-full bg-white p-10 sm:p-20 rounded-[4rem] shadow-2xl border-4 border-gray-50 flex flex-col items-center min-h-[60vh]">
               <div className="mb-20 text-center animate-in fade-in duration-1000">
                  <span className="quranic-typography text-4xl sm:text-6xl text-gray-300 opacity-60 italic">
                     {BISMILLAH}
                  </span>
               </div>

               <div className="flex flex-wrap justify-center gap-x-12 gap-y-16" dir="rtl">
                  {surah.verses.map((v, i) => (
                     <button 
                       key={i}
                       onClick={() => handleBoxClick(v, i)}
                       className={`flex items-center space-x-6 space-x-reverse transition-all duration-500 py-4 px-8 rounded-3xl ${isAnimating === i ? 'bg-amber-50 scale-105 shadow-inner' : 'hover:bg-gray-50'}`}
                     >
                        <span className="quranic-typography text-3xl sm:text-5xl text-gray-950 leading-[2.8]">
                           {v}
                        </span>
                        <div className="w-12 h-12 flex-shrink-0 rounded-full border-2 border-amber-100 flex items-center justify-center text-xs font-black text-amber-400 translate-y-3">
                           {i + 1}
                        </div>
                     </button>
                  ))}
               </div>
            </div>
         </div>

         <div className="w-full max-w-xl grid grid-cols-2 gap-6 pt-10 pb-8 bg-white/90 sticky bottom-0 z-30">
            <button onClick={handleSurahBack} className="py-6 bg-white border-2 border-gray-100 rounded-3xl font-black text-gray-400 hover:text-amber-600 transition-all uppercase tracking-widest text-[10px] flex items-center justify-center space-x-2">
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 19l-7-7 7-7"/></svg>
               <span>SEBELUMNYA</span>
            </button>
            <button onClick={handleSurahNext} disabled={selectedSurahIndex === JUZ_30_DATA.length - 1} className="py-6 bg-amber-600 rounded-3xl font-black text-white shadow-xl hover:brightness-110 transition-all uppercase tracking-widest text-[10px] flex items-center justify-center space-x-2 disabled:opacity-20">
               <span>SETERUSNYA</span>
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7"/></svg>
            </button>
         </div>
         <Copyright />
      </div>
    );
  }

  // Handle IQRA 8 Detailed View
  if (isIqra8) {
    const waqaf = IQRA_8_DATA[currentIndex];
    return (
      <div className="max-w-7xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
        <div className="w-full flex justify-between items-center mb-10">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-colors flex items-center space-x-2 group">
             <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center group-hover:bg-rose-50 transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
             </div>
             <span className="text-xs font-black uppercase tracking-widest">Batal</span>
          </button>
          <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
             <div className="h-full bg-rose-500 transition-all duration-700" style={{ width: `${progress}%` }}></div>
          </div>
          <div className="flex flex-col items-end">
            <span className="text-[10px] font-black text-rose-600 uppercase tracking-widest">{waqaf.name}</span>
            <span className="text-sm font-bold text-gray-900">{currentStep}/{totalSteps}</span>
          </div>
        </div>

        <div className="w-full max-w-4xl bg-white p-10 rounded-[4rem] shadow-2xl shadow-rose-900/10 border border-rose-50 flex flex-col items-center text-center space-y-6 mb-16">
          <div className="w-28 h-28 bg-rose-600 rounded-[2.5rem] flex items-center justify-center text-white text-5xl quranic-typography shadow-xl shadow-rose-200 rotate-3 transition-transform hover:rotate-0 duration-500">
            {waqaf.sign}
          </div>
          <div className="space-y-2">
            <h2 className="text-3xl font-black text-gray-900">{waqaf.name}</h2>
            <p className="px-8 py-3 bg-rose-50 text-rose-700 font-bold rounded-full border border-rose-100 text-base italic leading-relaxed">
              "{waqaf.rule}"
            </p>
          </div>
        </div>

        <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-8 mb-16" dir="rtl">
          {waqaf.examples.map((ex, idx) => (
            <button 
              key={idx}
              onClick={() => handleBoxClick(ex, idx)}
              className={`bg-white rounded-[3rem] border-2 border-gray-100 shadow-sm p-12 flex items-center justify-center text-center transition-all duration-500 hover:shadow-2xl hover:border-rose-200 hover:-translate-y-2 group ${isAnimating === idx ? 'scale-95 border-rose-500 bg-rose-50/20' : ''}`}
            >
              <span className="quranic-typography text-3xl sm:text-4xl text-gray-950 leading-[2.6] select-none block">
                {ex}
              </span>
              {isLoadingAudio && isAnimating === idx && (
                <div className="absolute top-6 left-6 w-8 h-8 border-4 border-rose-500 border-t-transparent rounded-full animate-spin"></div>
              )}
            </button>
          ))}
        </div>

        <div className="w-full max-w-xl grid grid-cols-2 gap-6 pb-12">
          <button onClick={prevItem} disabled={currentIndex === 0} className="py-6 bg-white border-2 border-gray-100 rounded-3xl font-black text-gray-400 hover:text-rose-600 disabled:opacity-20 transition-all uppercase tracking-widest text-[10px]">KEMBALI</button>
          <button onClick={nextItem} className="py-6 bg-rose-600 rounded-3xl font-black text-white shadow-xl hover:brightness-110 transition-all uppercase tracking-widest text-[10px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
    );
  }

  // Handle IQRA 1-7 Generic View
  const currentItems = Array.isArray(data[currentIndex]) ? data[currentIndex] : [data[currentIndex]];
  const isLargeFocus = isIqra1;
  const isAdvanced = level.id >= 5;

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center bg-white min-h-screen animate-in fade-in" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
      <div className="w-full flex justify-between items-center mb-10">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-2`}>
           <div className="w-10 h-10 rounded-full border border-gray-100 flex items-center justify-center hover:bg-emerald-50"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg></div>
           <span className="text-xs font-black uppercase tracking-widest">Batal</span>
        </button>
        <div className="flex-1 mx-8 h-1.5 bg-gray-50 rounded-full overflow-hidden shadow-inner">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-500`} style={{ width: `${progress}%` }}></div>
        </div>
        <div className="text-right">
          <span className={`text-[10px] font-black text-${colorTheme}-600 uppercase tracking-widest`}>{mode === 'SEQUENTIAL' ? (contentInfo?.tajuk || level.title) : 'REVIEW'}</span>
          <p className="text-sm font-bold text-gray-900">{currentStep}/{totalSteps}</p>
        </div>
      </div>

      <div className="w-full flex flex-col items-center space-y-10 flex-1 justify-center">
        {mode === 'SEQUENTIAL' && contentInfo && (
          <div className="text-center space-y-4 animate-in slide-in-from-top-4">
            <div className="space-y-1">
              <h2 className="text-3xl font-black text-gray-900">{contentInfo.tajuk}</h2>
              {isIqra7 && (
                <div className="flex flex-col items-center space-y-1 mt-2">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Cara Bacaan</span>
                  <p className={`text-sm font-black text-${colorTheme}-600 uppercase tracking-widest italic bg-${colorTheme}-50 px-6 py-2 rounded-full border border-${colorTheme}-100 shadow-sm`}>
                    {contentInfo.cara}
                  </p>
                </div>
              )}
            </div>
            <div className="flex flex-col items-center pt-2">
              <span className={`text-[10px] font-black text-${colorTheme}-500 uppercase tracking-widest`}>HURUF TERLIBAT</span>
              <span className={`text-4xl font-bold text-${colorTheme}-600 quranic-typography mt-1 drop-shadow-sm`}>{contentInfo.huruf}</span>
            </div>
          </div>
        )}

        {mode === 'SEQUENTIAL' && !contentInfo && (
          <div className="text-center space-y-2 animate-in slide-in-from-top-4">
            <h2 className="text-4xl font-black text-gray-900">{level.title}</h2>
            <p className="text-sm text-gray-400 font-bold uppercase tracking-widest">{level.subtitle}</p>
          </div>
        )}

        <div className={`w-full grid gap-8 ${isLargeFocus ? 'grid-cols-1 max-w-lg' : (level.id >= 4 ? 'grid-cols-1 max-w-4xl' : 'grid-cols-2 sm:grid-cols-3 max-w-5xl')}`} dir="rtl">
          {mode === 'SEQUENTIAL' ? (currentItems as string[]).map((word: string, idx: number) => (
            <button 
              key={idx} 
              onClick={() => handleBoxClick(word, idx)}
              className={`w-full bg-white shadow-xl border-4 border-gray-50 rounded-[4rem] flex items-center justify-center p-12 transition-all duration-500 relative group ${isAnimating === idx ? 'scale-95 border-emerald-400 bg-emerald-50/30 shadow-inner' : 'hover:scale-105 hover:shadow-2xl hover:border-emerald-100'}`}
            >
              <span className={`arabic-text font-black text-center transition-transform duration-500 select-none ${isLargeFocus ? 'text-[12rem] sm:text-[16rem] leading-none' : (isAdvanced ? 'text-5xl sm:text-6xl' : 'text-6xl sm:text-8xl')}`}>
                {word}
              </span>
              {isLoadingAudio && isAnimating === idx && (
                <div className="absolute top-10 left-10 w-10 h-10 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
              )}
            </button>
          )) : (
            <div className="col-span-full grid grid-cols-4 gap-6 w-full max-w-4xl p-10 bg-emerald-50 rounded-[4rem] border-2 border-emerald-100 animate-in zoom-in-95">
              {(reviewGrids[reviewPage] as string[]).map((letter: string, idx: number) => (
                <button 
                  key={idx} 
                  onClick={() => handleBoxClick(letter, idx)}
                  className={`aspect-square bg-white rounded-3xl flex items-center justify-center text-5xl font-black transition-all hover:scale-110 active:scale-90 border-2 border-transparent shadow-sm hover:border-emerald-300 ${isAnimating === idx ? 'scale-90 border-emerald-500 shadow-xl' : ''}`}
                >
                  <span className="arabic-text">{letter}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-6 mt-16 pb-12">
        <button onClick={mode === 'SEQUENTIAL' ? prevItem : prevReviewPage} disabled={mode === 'SEQUENTIAL' && currentIndex === 0} className="py-6 bg-white border-2 border-gray-100 rounded-3xl font-black text-gray-400 hover:text-emerald-600 transition-all uppercase tracking-widest text-[10px] shadow-sm">KEMBALI</button>
        <button onClick={mode === 'SEQUENTIAL' ? nextItem : nextReviewPage} className={`py-6 bg-${colorTheme}-600 rounded-3xl font-black text-white shadow-xl hover:brightness-110 transition-all uppercase tracking-widest text-[10px]`}>
          {mode === 'SEQUENTIAL' ? (currentIndex === data.length - 1 ? (hasReview ? 'ULANGKAJI' : 'SELESAI') : 'SETERUSNYA') : (reviewPage === 5 ? 'SELESAI' : 'SETERUSNYA')}
        </button>
      </div>
      <Copyright />
    </div>
  );
};

