                        {/* Clearest Quranic Text - Direct black for maximum clarity */}
                        <div className="flex-1">
                           <span className="quranic-typography text-3xl sm:text-4xl lg:text-5xl text-black block leading-tight drop-shadow-sm tracking-normal">
                              {v}
                           </span>
                        </div>
                     </button>
                  ))}
               </div>

               {/* Reward / Tip Area - Compact */}
               <div className="mt-8 pt-4 border-t border-gray-50 w-full text-center space-y-1">
                  <div className="inline-block p-1 bg-emerald-50 rounded-full text-lg">✨</div>
                  <h4 className="text-base font-black text-gray-900">Mumtaz!</h4>
                  <p className="text-[10px] text-gray-500 max-w-sm mx-auto">Satu huruf sepuluh kebaikan.</p>
               </div>
            </div>
         </div>

         {/* Fixed Navigation Buttons - Compact sizing */}
         <div className="w-full max-w-lg grid grid-cols-2 gap-3 pt-3 pb-5 bg-slate-50/95 backdrop-blur-sm sticky bottom-0 z-30 px-3">
            <button onClick={handleSurahBack} className="py-4 bg-white border border-gray-200 rounded-xl font-black text-gray-500 hover:text-amber-600 transition-all uppercase tracking-widest text-[9px] flex items-center justify-center space-x-2 shadow-sm active:scale-95">
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 19l-7-7 7-7"/></svg>
               <span>KEMBALI</span>
            </button>
