                </div>
              </button>
            ))}
          </div>
          <Copyright />
        </div>
      );
    }

    const surah = JUZ_30_DATA[selectedSurahIndex];
    return (
      <div className="max-w-7xl mx-auto p-4 md:p-6 flex flex-col items-center bg-slate-50 min-h-screen animate-in fade-in" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
