            >
              <span className={`arabic-text font-black text-center transition-transform duration-500 select-none ${isLargeFocus ? 'text-[10rem] sm:text-[14rem] leading-none' : (isAdvanced ? 'text-4xl sm:text-5xl' : 'text-5xl sm:text-7xl')}`}>
