          )) : (
            <div className="col-span-full grid grid-cols-4 gap-4 w-full max-w-3xl p-8 bg-emerald-50 rounded-[3rem] border-2 border-emerald-100 animate-in zoom-in-95">
              {(reviewGrids[reviewPage] as string[]).map((letter: string, idx: number) => (
                <button 
                  key={idx} 
                  onClick={() => handleBoxClick(letter, idx)}
                  className={`aspect-square bg-white rounded-2xl flex items-center justify-center text-4xl font-black transition-all hover:scale-110 active:scale-90 border-2 border-transparent shadow-sm hover:border-emerald-300 ${isAnimating === idx ? 'scale-90 border-emerald-500 shadow-xl' : ''}`}
