                  <span className="arabic-text">{letter}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="w-full max-w-xl grid grid-cols-2 gap-5 mt-16 pb-12">
        <button onClick={mode === 'SEQUENTIAL' ? prevItem : prevReviewPage} disabled={mode === 'SEQUENTIAL' && currentIndex === 0} className="py-5 bg-white border-2 border-gray-100 rounded-2xl font-black text-gray-400 hover:text-emerald-600 transition-all uppercase tracking-widest text-[10px] shadow-sm active:scale-95">KEMBALI</button>
        <button onClick={mode === 'SEQUENTIAL' ? nextItem : nextReviewPage} className={`py-5 bg-${colorTheme}-600 rounded-2xl font-black text-white shadow-xl hover:brightness-110 transition-all uppercase tracking-widest text-[10px] active:scale-95`}>
          {mode === 'SEQUENTIAL' ? (currentIndex === data.length - 1 ? (hasReview ? 'ULANGKAJI' : 'SELESAI') : 'SETERUSNYA') : (reviewPage === 5 ? 'SELESAI' : 'SETERUSNYA')}
        </button>
      </div>
      <Copyright />
    </div>
  );
};

