import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen.tsx';
import LoginPage from './components/LoginPage.tsx';
import ProfileSetup from './components/ProfileSetup.tsx';
import ProfileView from './components/ProfileView.tsx';
import LevelDetail from './components/LevelDetail.tsx';
import SubMenu from './components/SubMenu.tsx';
import PracticeSession from './components/PracticeSession.tsx';
import Quiz from './components/Quiz.tsx';
import Logo from './components/Logo.tsx';
import Copyright from './components/Copyright.tsx';
import { User, AppState, IqraLevel } from './types.ts';
import { IQRA_LEVELS } from './constants.tsx';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [animatingCardId, setAnimatingCardId] = useState<number | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  // Database Internal: Load from LocalStorage
  const [unlockedLevels, setUnlockedLevels] = useState<number[]>(() => {
    const saved = localStorage.getItem('advancekids_iqra_progress');
    return saved ? JSON.parse(saved) : [1];
  });

  useEffect(() => {
    // Load User from Database Internal
    const savedUser = localStorage.getItem('advancekids_user');
    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        setUser(u);
        // Admin automatically unlocks everything
        if (u.isAdmin) {
          setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        }
      } catch (e) { console.error("Database Error:", e); }
    }
  }, []);

  // Save to Database Internal whenever progress or user changes
  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    if (user) {
      localStorage.setItem('advancekids_user', JSON.stringify(user));
    }
  }, [unlockedLevels, user]);

  const handleSplashFinish = () => {
    // If user already exists in internal database, skip login/setup
    if (user) {
      setAppState(AppState.MENU);
    } else {
      setAppState(AppState.LOGIN);
    }
  };

  const handleLogin = (isAdmin?: boolean) => {
    if (isAdmin) {
      const adminUser: User = {
        name: 'Pentadbir Utama',
        email: 'admin@advancekids.com',
        age: 99,
        parentEmail: 'super@advancekids.com',
        photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Admin',
        isProfileComplete: true,
        isAdmin: true
      };
      setUser(adminUser);
      setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
      setAppState(AppState.MENU);
    } else {
      setAppState(AppState.PROFILE_SETUP);
    }
  };

  const handleProfileComplete = (newUser: User) => {
    setUser(newUser);
    setAppState(AppState.MENU);
  };

  const handleLevelSelect = (level: IqraLevel) => {
    if (!unlockedLevels.includes(level.id) && !user?.isAdmin) return;
    setAnimatingCardId(level.id);
    setTimeout(() => {
      setSelectedLevel(level);
      setAppState(AppState.SUBMENU);
      setAnimatingCardId(null);
    }, 400);
  };

  const handleSubMenuOption = (option: 'PRACTICE' | 'LEVEL' | 'QUIZ') => {
    if (option === 'PRACTICE') {
      setIsFromPracticePath(true);
      setAppState(AppState.PRACTICE);
    } else if (option === 'LEVEL') {
      setAppState(AppState.LEVEL);
    } else {
      setAppState(AppState.QUIZ);
    }
  };

  const unlockNextLevel = () => {
    if (selectedLevel && selectedLevel.id < IQRA_LEVELS.length) {
      const nextId = selectedLevel.id + 1;
      if (!unlockedLevels.includes(nextId)) {
        setUnlockedLevels(prev => [...prev, nextId]);
      }
    }
  };

  const renderContent = () => {
    switch (appState) {
      case AppState.SPLASH:
        return <SplashScreen onFinish={handleSplashFinish} />;
      case AppState.LOGIN:
        return <LoginPage onLogin={handleLogin} />;
      case AppState.PROFILE_SETUP:
        return <ProfileSetup onComplete={handleProfileComplete} />;
      case AppState.MENU:
        return (
          <div className="max-w-6xl mx-auto p-6 space-y-12 pb-20 fade-in flex flex-col min-h-screen">
            <header className="flex justify-between items-center py-4">
              <div className="flex items-center space-x-4">
                <Logo size="sm" />
                <h1 className="text-xl font-black text-[#1B1C57]">IQRA PINTAR</h1>
              </div>
              <button 
                onClick={() => setAppState(AppState.PROFILE_VIEW)}
                className="flex items-center space-x-3 bg-white p-2 pr-6 rounded-full shadow-lg border border-emerald-50 hover:scale-105 transition-all duration-300"
              >
                <img src={user?.photoURL} alt="avatar" className="w-10 h-10 rounded-full border-2 border-emerald-400 object-cover" />
                <div className="text-left">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Profil Anda</p>
                  <p className="text-sm font-bold text-gray-800">{user?.name.split(' ')[0]}</p>
                </div>
              </button>
            </header>

            <section className="text-center space-y-3">
              <h2 className="text-4xl md:text-5xl font-black text-[#1B1C57] leading-tight">Sedia untuk Belajar? 📖</h2>
              <p className="text-gray-500 max-w-xl mx-auto font-medium">Pilih tahap Iqra anda dan mulakan pengembaraan hari ini.</p>
            </section>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 flex-1">
              {IQRA_LEVELS.map((level) => {
                const isUnlocked = unlockedLevels.includes(level.id) || user?.isAdmin;
                return (
                  <button
                    key={level.id}
                    disabled={!isUnlocked}
                    onClick={() => handleLevelSelect(level)}
                    className={`relative p-8 rounded-[3rem] text-left transition-all duration-500 group overflow-hidden border-2 ${
                      isUnlocked 
                        ? 'bg-white border-transparent shadow-xl hover:-translate-y-2 hover:scale-[1.03] hover:shadow-2xl hover:border-emerald-200' 
                        : 'bg-gray-100 border-gray-200 opacity-80 cursor-not-allowed'
                    } ${animatingCardId === level.id ? 'scale-95' : ''}`}
                  >
                    {!isUnlocked && (
                      <div className="absolute inset-0 bg-gray-200/40 backdrop-blur-[2px] z-10 flex items-center justify-center">
                         <div className="bg-white/80 p-4 rounded-3xl shadow-xl flex flex-col items-center space-y-2 scale-in">
                            <span className="text-3xl">🔒</span>
                            <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Tahap Terkunci</span>
                         </div>
                      </div>
                    )}

                    <div className={`w-20 h-20 rounded-3xl flex items-center justify-center text-4xl mb-6 shadow-lg group-hover:scale-110 transition-transform duration-500 ${isUnlocked ? level.color : 'bg-gray-300'} text-white`}>
                      {level.icon}
                    </div>
                    <div className="space-y-2">
                      <div className="flex items-center space-x-3">
                        <h3 className={`text-2xl font-black ${isUnlocked ? 'text-[#1B1C57]' : 'text-gray-400'}`}>{level.title}</h3>
                        {isUnlocked && <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>}
                      </div>
                      <p className={`font-bold ${isUnlocked ? 'text-emerald-600' : 'text-gray-400'}`}>{level.subtitle}</p>
                      <p className={`text-sm leading-relaxed ${isUnlocked ? 'text-gray-500' : 'text-gray-300 blur-[1px]'}`}>{level.description}</p>
                    </div>
                  </button>
                );
              })}
            </div>
            <Copyright />
          </div>
        );
      case AppState.SUBMENU:
        return selectedLevel && (
          <div className="fade-in">
            <SubMenu 
              level={selectedLevel} 
              onBack={() => setAppState(AppState.MENU)} 
              onSelectOption={handleSubMenuOption} 
            />
          </div>
        );
      case AppState.LEVEL:
        return selectedLevel && (
          <div className="fade-in">
            <LevelDetail 
              level={selectedLevel} 
              onBack={() => setAppState(AppState.SUBMENU)} 
              showStartButton={true}
              onStartPractice={() => {
                setIsFromPracticePath(true);
                setAppState(AppState.PRACTICE);
              }}
            />
          </div>
        );
      case AppState.PRACTICE:
        return selectedLevel && (
          <div className="fade-in">
            <PracticeSession 
              level={selectedLevel} 
              onBack={() => setAppState(AppState.SUBMENU)} 
              onFinish={() => setAppState(AppState.QUIZ)} 
            />
          </div>
        );
      case AppState.QUIZ:
        return selectedLevel && (
          <div className="fade-in">
            <Quiz 
              level={selectedLevel} 
              onBack={() => setAppState(AppState.SUBMENU)} 
              onFinish={() => {
                unlockNextLevel();
                setAppState(AppState.MENU);
              }}
            />
          </div>
        );
      case AppState.PROFILE_VIEW:
        return user && (
          <div className="fade-in">
            <ProfileView 
              user={user} 
              unlockedLevels={unlockedLevels} 
              levels={IQRA_LEVELS} 
              onBack={() => setAppState(AppState.MENU)}
              onUpdateUser={(updated) => setUser(updated)}
            />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen transition-all duration-700 ease-in-out">
      {renderContent()}
    </div>
  );
};

export default App;

