import { GoogleGenAI, Type } from "@google/genai";

const SYLLABUS_MAP: Record<number, string> = {
  1: "Fokus: Huruf tunggal Hijaiyah baris Fathah.",
  2: "Fokus: Kasrah (bunyi 'i') dan Dhommah (bunyi 'u').",
  3: "Fokus: Tanween (an, in, un).",
  4: "Fokus: Huruf Bersambung.",
  5: "Fokus: Hukum Mad & Sukun.",
  6: "Fokus: Syaddah (Sabdu).",
  7: "Fokus: Hukum Nun/Mim Mati & Dengung.",
  8: "Fokus: Tanda Waqaf & Sujud Tilawah."
};

export async function getLevelGuidance(levelTitle: string, subtitle: string) {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Berikan penerangan ringkas dan 3 contoh perkataan untuk tajuk pembelajaran agama: ${levelTitle} - ${subtitle}. Gunakan bahasa yang mudah untuk kanak-kanak.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            explanation: { type: Type.STRING },
            examples: { type: Type.ARRAY, items: { type: Type.STRING } },
            tips: { type: Type.STRING }
          },
          required: ['explanation', 'examples', 'tips']
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return null;
  }
}

export async function getQuizQuestions(levelId: number, levelTitle: string, subtitle: string, count: number = 10) {
  try {
    const syllabus = SYLLABUS_MAP[levelId] || `Fokus pada ${levelTitle}`;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Bertindak sebagai Guru Al-Quran pakar. Hasilkan ${count} soalan kuiz untuk ${levelTitle} (${subtitle}). Silibus: ${syllabus}. Format JSON sahaja.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  question: { type: Type.STRING },
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  correctIndex: { type: Type.INTEGER },
                  explanation: { type: Type.STRING }
                },
                required: ['question', 'options', 'correctIndex', 'explanation']
              }
            }
          },
          required: ['questions']
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Quiz Error:", error);
    return null;
  }
}

import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen.tsx';
import LoginPage from './components/LoginPage.tsx';
import ProfileSetup from './components/ProfileSetup.tsx';
import ProfileView from './components/ProfileView.tsx';
import LevelDetail from './components/LevelDetail.tsx';
import SubMenu from './components/SubMenu.tsx';
import PracticeSession from './components/PracticeSession.tsx';
import Quiz from './components/Quiz.tsx';
import { User, AppState, IqraLevel } from './types.ts';
import { IQRA_LEVELS } from './constants.tsx';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);

  const [unlockedLevels, setUnlockedLevels] = useState<number[]>(() => {
    const saved = localStorage.getItem('advancekids_iqra_progress');
    return saved ? JSON.parse(saved) : [1];
  });

  useEffect(() => {
    const savedUser = localStorage.getItem('advancekids_user');
    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        setUser(u);
        if (u.isAdmin) setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    if (user) localStorage.setItem('advancekids_user', JSON.stringify(user));
  }, [unlockedLevels, user]);

  const handleLevelSelect = (level: IqraLevel) => {
    if (unlockedLevels.includes(level.id) || user?.isAdmin) {
      setSelectedLevel(level);
      setAppState(AppState.SUBMENU);
    }
  };

  const renderContent = () => {
    switch (appState) {
      case AppState.SPLASH: return <SplashScreen onFinish={() => user ? setAppState(AppState.MENU) : setAppState(AppState.LOGIN)} />;
      case AppState.LOGIN: return <LoginPage onLogin={(admin) => admin ? (setUser({ name: 'Admin', email: 'admin@advancekids.com', age: 99, parentEmail: 'admin@advancekids.com', photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Admin', isProfileComplete: true, isAdmin: true }), setUnlockedLevels([1,2,3,4,5,6,7,8,9]), setAppState(AppState.MENU)) : setAppState(AppState.PROFILE_SETUP)} />;
      case AppState.PROFILE_SETUP: return <ProfileSetup onComplete={(u) => { setUser(u); setAppState(AppState.MENU); }} />;
      case AppState.MENU: return (
        <div className="max-w-6xl mx-auto p-6 space-y-12 pb-20 fade-in flex flex-col min-h-screen">
          <header className="flex justify-between items-center py-4">
            <h1 className="text-xl font-black text-[#1B1C57]">IQRA PINTAR</h1>
            <button onClick={() => setAppState(AppState.PROFILE_VIEW)} className="flex items-center space-x-3 bg-white p-2 rounded-full shadow-lg">
              <img src={user?.photoURL} className="w-10 h-10 rounded-full border-2 border-emerald-400" />
              <span className="text-sm font-bold pr-4">{user?.name}</span>
            </button>
          </header>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
            {IQRA_LEVELS.map(level => (
              <button key={level.id} onClick={() => handleLevelSelect(level)} className={`p-8 rounded-[3rem] text-left transition-all bg-white shadow-xl ${!unlockedLevels.includes(level.id) && !user?.isAdmin ? 'opacity-50 grayscale' : 'hover:scale-105'}`}>
                <div className={`w-16 h-16 rounded-2xl ${level.color} flex items-center justify-center text-3xl mb-4`}>{level.icon}</div>
                <h3 className="text-xl font-black">{level.title}</h3>
                <p className="text-sm text-gray-500">{level.subtitle}</p>
              </button>
            ))}
          </div>
        </div>
      );
      case AppState.SUBMENU: return selectedLevel && <SubMenu level={selectedLevel} onBack={() => setAppState(AppState.MENU)} onSelectOption={(opt) => setAppState(opt as any)} />;
      case AppState.PRACTICE: return selectedLevel && <PracticeSession level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.QUIZ)} />;
      case AppState.QUIZ: return selectedLevel && <Quiz level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => { if (selectedLevel.id < 9 && !unlockedLevels.includes(selectedLevel.id + 1)) setUnlockedLevels([...unlockedLevels, selectedLevel.id + 1]); setAppState(AppState.MENU); }} />;
      case AppState.PROFILE_VIEW: return user && <ProfileView user={user} unlockedLevels={unlockedLevels} levels={IQRA_LEVELS} onBack={() => setAppState(AppState.MENU)} onUpdateUser={setUser} />;
      default: return null;
    }
  };

  return <div className="min-h-screen bg-slate-50">{renderContent()}</div>;
};

export default App;

