import Copyright from './Copyright';
import { 
  IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, 
  IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA 
