          .subtitle { text-align: center; color: #059669; font-size: 14pt; margin-bottom: 30px; }
          .arabic-table { width: 100%; border-collapse: collapse; direction: rtl; }
          .arabic-table td { border: 1px solid #ddd; padding: 15px; text-align: center; font-size: 22pt; font-family: 'Arial Unicode MS', serif; }
          .waqaf-item { margin-bottom: 15px; border-bottom: 1px solid #eee; padding: 10px; }
        </style>
      </head>
      <body>
        <div class="title">ADVANCEKIDS IQRA PINTAR</div>
        <div class="subtitle">Nota Pembelajaran: ${level.title} (${level.subtitle})</div>
    `;

    let content = "";

    const chunk = (arr: any[], size: number) => {
      const res = [];
      for (let i = 0; i < arr.length; i += size) res.push(arr.slice(i, i + size));
      return res;
    };

    if (level.id === 1) {
      content += `<table class="arabic-table">${chunk(IQRA_1_LETTERS, 6).map(row => `<tr>${row.map(l => `<td>${l}</td>`).join('')}</tr>`).join('')}</table>`;
    } else if (level.id === 2) {
      content += `<table class="arabic-table">${IQRA_2_DATA.map(row => `<tr>${row.map(l => `<td>${l}</td>`).join('')}</tr>`).join('')}</table>`;
    } else if (level.id === 3) {
      content += `<table class="arabic-table">${IQRA_3_DATA.map(row => `<tr>${row.map(l => `<td>${l}</td>`).join('')}</tr>`).join('')}</table>`;
    } else if (level.id === 4) {
      content += `<table class="arabic-table">${IQRA_4_DATA.map(row => `<tr>${row.map(l => `<td>${l}</td>`).join('')}</tr>`).join('')}</table>`;
    } else if (level.id === 5) {
      content += `<table class="arabic-table">${IQRA_5_DATA.map(row => `<tr>${row.map(l => `<td>${l}</td>`).join('')}</tr>`).join('')}</table>`;
    } else if (level.id === 6) {
      content += `<table class="arabic-table">${IQRA_6_DATA.map(row => `<tr>${row.map(l => `<td>${l}</td>`).join('')}</tr>`).join('')}</table>`;
    } else if (level.id === 7) {
      content += `<table class="arabic-table">${IQRA_7_DATA.map(row => `<tr>${row.map(l => `<td>${l}</td>`).join('')}</tr>`).join('')}</table>`;
    } else if (level.id === 8) {
      content += IQRA_8_DATA.map(w => `<div class="waqaf-item"><b>${w.sign} (${w.name})</b>: ${w.rule}<br/><span style="font-size:18pt;">${w.examples.join(' | ')}</span></div>`).join('');
    } else {
      content += `<p style="text-align:center;">Silibus Juz 30 boleh dirujuk terus dalam aplikasi.</p>`;
    }

    const footer = "</body></html>";
    const blob = new Blob(['\ufeff', header + content + footer], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Nota_${level.title.replace(' ', '_')}.doc`;
    link.click();
  };

  return (
    <div className="max-w-2xl mx-auto p-6 md:p-12 animate-in fade-in zoom-in-95 duration-300 min-h-screen flex flex-col">
      <div className="flex items-center space-x-4 mb-8">
        <button onClick={onBack} className="p-3 bg-white shadow-sm rounded-2xl hover:bg-gray-50 text-emerald-600 transition-colors">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
        </button>
        <div>
          <h2 className="text-3xl font-bold text-gray-900">{level.title}</h2>
          <p className="text-emerald-600 font-medium">{level.subtitle}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4 flex-1">
        {options.map((opt) => (
          <button
            key={opt.id}
            onClick={() => onSelectOption(opt.id as any)}
            className="flex items-center p-6 bg-white border border-gray-100 rounded-3xl shadow-sm hover:shadow-md hover:border-emerald-200 hover:-translate-y-1 transition-all group text-left"
          >
            <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl group-hover:scale-110 transition-transform">
              {opt.icon}
            </div>
            <div className="ml-6 flex-1">
              <h3 className="text-xl font-bold text-gray-900 group-hover:text-emerald-700">{opt.title}</h3>
              <p className="text-gray-500">{opt.desc}</p>
            </div>
            <div className="text-emerald-300 group-hover:text-emerald-600 transition-colors">
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
              </svg>
            </div>
          </button>
        ))}

        {/* Butang Word Baru */}
        <button
          onClick={exportSingleToWord}
          className="flex items-center p-6 bg-blue-50 border-2 border-blue-100 rounded-3xl shadow-sm hover:shadow-md hover:border-blue-400 hover:-translate-y-1 transition-all group text-left mt-4"
        >
          <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl group-hover:rotate-12 transition-transform shadow-lg">
            📄
          </div>
          <div className="ml-6 flex-1">
            <h3 className="text-xl font-bold text-blue-900">Muat Turun Word</h3>
            <p className="text-blue-600/70 font-medium">Simpan nota {level.title} ke telefon/PC</p>
          </div>
          <div className="text-blue-400 group-hover:text-blue-600 transition-colors">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
          </div>
        </button>
      </div>
      <Copyright />
    </div>
  );
};

export default SubMenu;
